window.__EBT=window.__EBT||{};window.__EBT["ro"]=window.__EBT["ro"]||{};window.__EBT["ro"]["1Chr"]=[[1,[[1,"Adam, Set, Enos,"],[2,"Kenan, Mahalalel, Jared,"],[3,"Enoh, Matusalah, Lameh,"],[4,"Noe, Sem, Ham și Iafet."],[5,"Fiii lui Iafet: Gomer, Magog, Madai, Javan, Tubal, Meșec și Tiras."],[6,"Fiii lui Gomer: Așkenaz, Difat și Togarma."],[7,"Fiii lui Iavan: Elisa, Tarsis, Chitim și Rodanim."],[8,"Fiii lui Ham: Cuș, Mițraim, Put și Canaan."],[9,"Fiii lui Cuș: Seba, Havila, Sabta, Rama și Sabteca. Fiii lui Raama: Seba și Dedan."],[10,"Cuș a născut pe Nimrod. El a început să fie un puternic pe pământ."],[11,"Mițraim a născut pe Ludim, Anamim, Lehabim, Naftuhim,"],[12,"Patrusim, Casluhim (de unde au venit filistenii) și Caphtorim."],[13,"Canaan a născut pe Sidon, întâiul său născut, Het,"],[14,"iebusitul, amoritul, ghirgasitul,"],[15,"hevitul, arhitul, sinitul,"],[16,"arvaditul, zemaritul și hamatitul."],[17,"Fiii lui Sem: Elam, Așur, Arpacșad, Lud, Aram, Uț, Hul, Gheter și Meșec."],[18,"Arpacşad a născut pe Şela, iar Şela a născut pe Eber."],[19,"Lui Eber i s-au născut doi fii: numele unuia era Peleg, căci în zilele lui pământul era împărțit; și numele fratelui său era Ioctan."],[20,"Ioctan a născut pe Almodad, Șelef, Hazarmavet, Ierah,"],[21,"Hadoram, Uzal, Diklah,"],[22,"Ebal, Abimael, Saba,"],[23,"Ofir, Havila și Iobab. Toți aceștia au fost fiii lui Ioctan."],[24,"Sem, Arpachshad, Shelah,"],[25,"Eber, Peleg, Reu,"],[26,"Serug, Nahor, Terah,"],[27,"Avram (numit și Avraam)."],[28,"Fiii lui Avraam: Isaac și Ismael."],[29,"Acestea sunt generațiile lor: întâiul născut al lui Ismael, Nebaiot; apoi Chedar, Adbeel, Mibsam,"],[30,"Mishma, Dumah, Massa, Hadad, Tema,"],[31,"Jetur, Nafiș și Chedema. Aceștia sunt fiii lui Ismael."],[32,"Fiii lui Chetura, concubina lui Avraam: ea a născut pe Zimran, Iocșan, Medan, Madian, Ișbac și Șua. Fiii lui Iocșan: Șeba și Dedan."],[33,"Fiii lui Madian: Efa, Efer, Hanoh, Abida și Eldaa. Toți aceștia au fost fiii lui Chetura."],[34,"Avraam a devenit tatăl lui Isaac. Fiii lui Isaac: Esau și Israel."],[35,"Fiii lui Esau: Elifaz, Reuel, Ieuș, Ialam și Core."],[36,"Fiii lui Elifaz: Teman, Omar, Țefi, Gatam, Chenaz, Timna și Amalec."],[37,"Fiii lui Reuel: Nahat, Zerah, Șama și Miza."],[38,"Fiii lui Seir: Lotan, Șobal, Țibeon, Ana, Dishon, Ezer și Disan."],[39,"Fiii lui Lotan: Hori și Homam; iar Timna era sora lui Lotan."],[40,"Fiii lui Șobal: Alian, Manahat, Ebal, Șefi și Onam. Fiii lui Țibeon: Aia și Ana."],[41,"Fiul lui Ana: Dishon. Fiii lui Dishon: Hamran, Eșban, Itran și Cheran."],[42,"Fiii lui Ezer: Bilhan, Zaavan și Iaakan. Fiii lui Disan: Uz și Aran."],[43,"Iată care sunt împărații care au domnit în țara Edomului, înainte ca vreun rege să domnească peste copiii lui Israel: Bela, fiul lui Beor; şi numele cetăţii lui era Dinhaba."],[44,"Bela a murit și în locul lui a domnit Iobab, fiul lui Zerah din Boțra."],[45,"Iobab a murit și în locul lui a domnit Hușam din țara Temaniților."],[46,"Hușam a murit și în locul lui a domnit Hadad, fiul lui Bedad, care a lovit Madian în câmpul Moabului; și numele orașului său era Avit."],[47,"Hadad a murit, iar în locul lui a domnit Samla din Masreca."],[48,"Samla a murit și în locul lui a domnit Saul din Rehobot de lângă râu."],[49,"Saul a murit și în locul lui a domnit Baal Hanan, fiul lui Acbor."],[50,"Baal Hanan a murit și Hadad a domnit în locul lui; și numele orașului său era Pai. Numele soției lui era Mehetabel, fiica lui Matred, fiica lui Mezahab."],[51,"Atunci Hadad a murit. Căpeteniile Edomului erau: căpetenia Timna, căpetenia Aliah, căpetenia Ietet,"],[52,"căpetenia Oholibamah, căpetenia Elah, căpetenia Pinon,"],[53,"șeful Kenaz, șeful Teman, șeful Mibzar,"],[54,"căpetenia Magdiel și căpetenia Iram. Aceștia sunt căpeteniile Edomului."]]],[2,[[1,"Aceștia sunt fiii lui Israel: Ruben, Simeon, Levi, Iuda, Isahar, Zabulon,"],[2,"Dan, Iosif, Beniamin, Neftali, Gad și Așer."],[3,"Fiii lui Iuda: Er, Onan și Șela, care trei i s-au născut din fiica lui Sua, canaanitea. Er, întâiul născut al lui Iuda, a fost rău în ochii Domnului; și l-a ucis."],[4,"Tamar, nora lui, i-a născut pe Pereț și pe Zerah. Toți fiii lui Iuda au fost cinci."],[5,"Fiii lui Pereț: Hețron și Hamul."],[6,"Fiii lui Zerah: Zimri, Etan, Heman, Calcol și Dara - cinci dintre ei în total."],[7,"Fiul lui Carmi: Ahar, tulburătorul lui Israel, care a săvârșit o greșeală în lucrul devotat."],[8,"Fiul lui Etan: Azaria."],[9,"De asemenea, fiii lui Hețron, care i s-au născut: Ierahmeel, Ram și Chelubai."],[10,"Ram a născut pe Aminadab, iar Aminadab a născut pe Nahșon, prințul copiilor lui Iuda;"],[11,"și Nahșon a născut pe Salma, iar Salma a născut pe Boaz,"],[12,"și Boaz a născut pe Obed și Obed a născut pe Isai;"],[13,"și Isai a născut pe primul său născut, Eliab, pe Abinadab al doilea, și pe Simea pe al treilea,"],[14,"Netanel al patrulea, Raddai al cincilea,"],[15,"Ozem al șaselea și David al șaptelea;"],[16,"şi surorile lor erau Ţeruia şi Abigail. Fiii lui Țeruia: Abisai, Ioab și Asael, trei."],[17,"Abigail a născut pe Amasa; iar tatăl lui Amasa a fost Ieter Ismaelitul."],[18,"Caleb, fiul lui Hețron, a născut copii din soția sa Azuba și din Ieriot; și aceștia au fost fiii ei: Ieșer, Șobab și Ardon."],[19,"Azuba a murit și Caleb s-a căsătorit cu Efrata, care i-a născut Hur."],[20,"Hur a născut pe Uri, iar Uri a născut pe Bețalel."],[21,"După aceea, Hețron a intrat la fiica lui Machir, tatăl Galaadului, pe care a luat-o de soție când avea șaizeci de ani; iar ea i-a născut pe Segub."],[22,"Segub a născut pe Iair, care avea douăzeci și trei de cetăți în țara Galaadului."],[23,"Gheșur și Aram au luat de la ei cetățile Iairului, Chenatul și satele lui, chiar șaizeci de orașe. Toți aceștia au fost fiii lui Machir, tatăl Galaadului."],[24,"După ce Hețron a murit în Caleb Efrata, Abia, soția lui Hețron, i-a născut Așhur, tatăl lui Tecoa."],[25,"Fiii lui Ierahmeel, întâiul născut al lui Hețron, au fost Ram, întâiul născut, Buna, Oren, Oțem și Ahija."],[26,"Ierahmeel avea o altă soție, al cărei nume era Atarah. Ea a fost mama lui Onam."],[27,"Fiii lui Ram, întâiul născut al lui Ierahmeel, au fost Maaz, Iamin și Eker."],[28,"Fiii lui Onam au fost Șamai și Iada. Fiii lui Șamai: Nadab și Abișur."],[29,"Numele soției lui Abișur era Abihail; și ea i-a născut pe Ahban și pe Molid."],[30,"Fiii lui Nadab: Seled și Apaim; dar Seled a murit fără copii."],[31,"Fiul lui Appaim: Ishi. Fiul lui Iși: Șesan. Fiul lui Șesan: Ahlai."],[32,"Fiii lui Iada, fratele lui Șamai: Ieter și Ionatan; iar Jether a murit fără copii."],[33,"Fiii lui Ionatan: Pelet și Zaza. Aceștia au fost fiii lui Ierahmeel."],[34,"Acum Șeșan nu avea fii, ci doar fiice. Șesan avea un slujitor, un egiptean, al cărui nume era Iarha."],[35,"Șesan și-a dat de soție fiica lui Iarha, slujitorului său; iar ea i-a născut pe Attai."],[36,"Attai a născut pe Natan, iar Natan a născut pe Zabad,"],[37,"și Zabad a născut pe Ephlal, iar Eflal a născut pe Obed,"],[38,"și Obed a născut pe Iehu și Iehu a născut pe Azaria,"],[39,"și Azaria a născut pe Helez și Helez a născut pe Eleasa,"],[40,"şi Eleasa a născut pe Sismai, iar Sismai a născut pe Şalum,"],[41,"şi Şalum a născut pe Iecamia, iar Iecamia a născut pe Elişama."],[42,"Fiii lui Caleb, fratele lui Ierahmeel, au fost Meşa, întâiul său născut, care a fost tatăl lui Zif, şi fiii lui Mareşa, tatăl Hebronului."],[43,"Fiii lui Hebron: Core, Tapuah, Rekem și Șema."],[44,"Sema a născut pe Raham, tatăl lui Iorkeam; şi Rekem a născut pe Şamai."],[45,"Fiul lui Șamai a fost Maon; şi Maon a fost tatăl lui Bet-Ţur."],[46,"Efa, concubina lui Caleb, a născut pe Haran, Moza și Gazez; iar Haran a născut pe Gazez."],[47,"Fiii lui Iahdai: Regem, Iotan, Gheșan, Pelet, Efa și Șaaf."],[48,"Maaca, concubina lui Caleb, a născut pe Șeber și pe Tirhana."],[49,"Ea a născut de asemenea pe Şaaf, tatăl lui Madmana, pe Şeva, tatăl Macbenei şi tatăl lui Ghibea; iar fiica lui Caleb era Acsa."],[50,"Aceștia au fost fiii lui Caleb, fiul lui Hur, întâiul născut al lui Efrata: Șobal, tatăl lui Chiriat-Iearim,"],[51,"Salma, tatăl lui Betleem, și Haref, tatăl lui Bet Gader."],[52,"Șobal, tatăl lui Chiriat-Iearim, a avut fii: Haroeh, jumătate din Menioth."],[53,"Familiile lui Chiriat-Iearim: Itriții, Putiții, Șumații și Mișraiții; din ei au venit zoratiții și eștaoliții."],[54,"Fiii lui Salma: Betleem, netofatiții, Atrot-Bet-Ioab și jumătate dintre manahatiți, zoriții."],[55,"Familiile de cărturari care locuiau la Iabeț: Tirahiții, Șimeații și Sucații. Aceștia sunt cheniții care au venit din Hammat, tatăl casei lui Recab."]]],[3,[[1,"Aceștia au fost fiii lui David, care i s-au născut la Hebron: întâiul născut, Amnon, din Ahinoam, Izreelita; al doilea, Daniel, din Abigail Carmelitana;"],[2,"al treilea, Absalom, fiul lui Maaca, fiica lui Talmai, regele Gheșurului; al patrulea, Adonia, fiul lui Haghit;"],[3,"al cincilea, Şefatia din Abital; al șaselea, Itream de către soția lui Egla;"],[4,"lui i s-au născut șase în Hebron; și a domnit acolo șapte ani și șase luni. El a domnit treizeci şi trei de ani la Ierusalim;"],[5,"şi aceştia i s-au născut la Ierusalim: Şimea, Şobab, Natan şi Solomon, patru, de la Batşua, fiica lui Amiel;"],[6,"și Ibhar, Elishama, Elifelet,"],[7,"Nogah, Nepheg, Japhia,"],[8,"Elishama, Eliada și Elifelet, nouă."],[9,"Toți aceștia au fost fiii lui David, pe lângă fiii concubinelor; iar Tamar era sora lor."],[10,"Fiul lui Solomon a fost Roboam, Abia, fiul său, Asa, fiul său, Iosafat, fiul său,"],[11,"Ioram, fiul său, Ahazia, fiul său, Ioas, fiul său,"],[12,"Amazia, fiul său, Azaria, fiul său, Iotam, fiul său,"],[13,"fiul său Ahaz, fiul său Ezechia, fiul său Manase,"],[14,"fiul său Amon și fiul său Iosia."],[15,"Fiii lui Iosia: întâiul născut Iohanan, al doilea Ioiachim, al treilea Zedechia și al patrulea Șalum."],[16,"Fiii lui Ioiachim: Ieconia, fiul său, și Zedechia, fiul său."],[17,"Fiii lui Ieconia, captivul: Șealtiel, fiul său,"],[18,"Malchiram, Pedaia, Șenațar, Iekamia, Hoșama și Nedabia."],[19,"Fiii lui Pedaia: Zorobabel și Șimei. Fiii lui Zorobabel: Meșulam și Hanania; şi Şelomit era sora lor;"],[20,"și Hașuba, Ohel, Berechia, Hasadia și Iusab Hesed, cinci."],[21,"Fiii lui Hanania: Pelatia și Iesaia; fiii lui Refaia, fiii lui Arnan, fiii lui Obadia, fiii lui Șecania."],[22,"Fiul lui Şecania: Şemaia. Fiii lui Șemaia: Hatuș, Igal, Baria, Nearia și Șafat, șase."],[23,"Fiii lui Nearia: Elioenai, Ezeia și Azrikam, trei."],[24,"Fiii lui Elioenai: Hodavia, Eliașib, Pelaia, Akub, Iohanan, Delaia și Anani, șapte."]]],[4,[[1,"Fiii lui Iuda: Pereț, Hețron, Carmi, Hur și Șobal."],[2,"Reaia, fiul lui Şobal, a născut pe Iahat; și Iahat a născut pe Ahumai și pe Lahad. Acestea sunt familiile zoratiților."],[3,"Aceștia au fost fiii tatălui lui Etam: Izreel, Isma și Idbaș. Numele surorii lor era Hazzelelponi."],[4,"Penuel a fost tatăl lui Ghedor și Ezer, tatăl lui Hușa. Aceștia sunt fiii lui Hur, întâiul născut al lui Efrata, tatăl Betleemului."],[5,"Așhur, tatăl lui Tecoa, a avut două neveste, Hela și Naara."],[6,"Naara i-a născut pe Ahuzam, Hefer, Temeni și Haahaștari. Aceștia au fost fiii lui Naara."],[7,"Fiii lui Hela au fost Zeret, Ițehar și Etnan."],[8,"Hacoț a născut pe Anub, pe Țobeba și pe familiile lui Aharhel, fiul lui Harum."],[9,"Iabeț era mai onorabil decât frații săi. Mama lui i-a pus numele Iabez, zicând: „Pentru că l-am născut cu întristare”."],[10,"Iabeț a chemat pe Dumnezeul lui Israel și a zis: „O, dacă m-ai binecuvânta într-adevăr și mi-ai lărgi hotarul! mâna Ta să fie cu mine și să mă păzești de rău, ca să nu provoc durere!”"],[11,"Chelub, fratele lui Şuha, a născut pe Mehir, care a fost tatăl lui Eşton."],[12,"Eșton a născut pe Bet-Rafa, pe Paseah și pe Tehinna, tatăl lui Ir Nahaș. Aceștia sunt oamenii din Reca."],[13,"Fiii lui Chenaz: Otniel și Seraia. Fiii lui Otniel: Hathat."],[14,"Meonothai a născut pe Ofra, iar Seraia a născut pe Ioab, tatăl lui Ghe Harashim, pentru că erau meșteri."],[15,"Fiii lui Caleb, fiul lui Iefune: Iru, Ela și Naam. Fiul lui Ela: Chenaz."],[16,"Fiii lui Iehalelel: Zif, Zifa, Tiria și Asarel."],[17,"Fiii lui Ezra: Ieter, Mered, Efer și Ialon; și soția lui Mered a născut pe Miriam, Șamai și Ișba, tatăl Eștemoei."],[18,"Soția sa, evreica, i-a născut pe Iered, tatăl lui Ghedor, pe Heber, tatăl lui Soco și pe Iekutiel, tatăl lui Zanoah. Aceștia sunt fiii lui Bitia, fiica lui Faraon, pe care i-a luat Mered."],[19,"Fiii soției lui Hodia, sora lui Naham, au fost părinții lui Cheila, Garmita, și ai Eștemoa, Maaatitul."],[20,"Fiii lui Șimon: Amnon, Rina, Ben Hanan și Tilon. Fiii lui Iși: Zohet și Ben Zohet."],[21,"Fiii lui Şela, fiul lui Iuda: Er, tatăl lui Leca, Laada, tatăl lui Mareşa, şi familiile casei celor ce lucrau in subţire, din casa Asbea;"],[22,"și Iochim și bărbații din Cozeba și Ioas și Saraf, care stăpâneau în Moab și Iașubileem. Aceste înregistrări sunt vechi."],[23,"Aceștia erau olarii și locuitorii din Netaim și Ghedera; locuiau acolo cu regele pentru munca lui."],[24,"Fiii lui Simeon: Nemuel, Iamin, Iarib, Zerah, Saul;"],[25,"Șalum, fiul său, Mibsam, fiul său, și Mișma, fiul său."],[26,"Fiii lui Mișma: Hamuel, fiul său, Zacur, fiul său, Șimei, fiul său."],[27,"Şimei a avut şaisprezece fii şi şase fiice; dar frații lui nu au avut mulți copii și toată familia lor nu s-a înmulțit ca fiii lui Iuda."],[28,"Ei locuiau la Beer-Șeba, Moladah, Hazarșual,"],[29,"la Bilha, la Ezem, la Tolad,"],[30,"la Betuel, la Horma, la Țiclag,"],[31,"la Bet-Marcabot, Hazar-Susim, la Bet-Biri și la Șaraim. Acestea au fost cetățile lor până la domnia lui David."],[32,"Satele lor erau Etam, Ain, Rimon, Tochen și Așan, cinci cetăți;"],[33,"și toate satele lor care erau în jurul acelorași cetăți, până la Baal. Acestea erau așezările lor și își păstrau genealogia."],[34,"Meșobab, Jamlec, Iosah, fiul lui Amazia,"],[35,"Ioel, Iehu, fiul lui Iosibia, fiul lui Seraia, fiul lui Asiel,"],[36,"Elioenai, Iacoba, Iesohaiah, Asaia, Adiel, Iesimiel, Benaia,"],[37,"și Ziza, fiul lui Șifi, fiul lui Alon, fiul lui Iedaia, fiul lui Șimri, fiul lui Șemaia,"],[38,"aceştia pomeniţi pe nume erau prinţi în familiile lor. Casele părinților lor au crescut foarte mult."],[39,"S-au dus până la intrarea în Ghedor, chiar în partea de răsărit a văii, să caute pășune pentru turmele lor."],[40,"Au găsit pășuni bogate și bune, iar pământul era larg, liniștit și pașnic, pentru că cei care locuiau acolo înainte erau descendenți din Ham."],[41,"Aceştia scrise pe nume au venit în zilele lui Ezechia, împăratul lui Iuda, şi le-au lovit corturile şi pe Meunimii care se aflau acolo; și i-au nimicit cu desăvârșire până în ziua de azi și au locuit la locul lor, pentru că acolo era pășune pentru turmele lor."],[42,"Unii dintre ei, chiar din fiii lui Simeon, cinci sute de oameni, au mers pe muntele Seir, având ca căpetenii pe Pelatia, Nearia, Refaia și Uziel, fiii lui Iși."],[43,"Au lovit rămășița amaleciților care au scăpat și au locuit acolo până astăzi."]]],[5,[[1,"Fiii lui Ruben, întâiul născut al lui Israel (căci el era întâiul născut, dar pentru că a spurcat patul tatălui său, dreptul lui de întâi născut a fost dat fiilor lui Iosif, fiul lui Israel; și genealogia nu trebuie înscrisă după dreptul de întâi născut."],[2,"Căci Iuda a biruit peste frații săi și de la el a venit prințul; dar dreptul de întâi născut era al lui Iosif)—"],[3,"fiii lui Ruben, întâiul născut al lui Israel: Hanoh, Palu, Hețron și Carmi."],[4,"Fiii lui Ioel: Șemaia, fiul său, Gog, fiul său, Șimei, fiul său,"],[5,"Fiul său Mica, fiul său Reaia, fiul său Baal,"],[6,"și Beera, fiul său, pe care Tilgat Pilneser, regele Asiriei, l-a luat în robie. El a fost prinț al rubeniților."],[7,"Frații lui, după familiile lor, când a fost înscrisă genealogia generațiilor lor: căpetenia, Ieiel și Zaharia,"],[8,"și Bela, fiul lui Azaz, fiul lui Șema, fiul lui Ioel, care locuia în Aroer, până la Nebo și Baal Meon;"],[9,"și a locuit spre răsărit până la intrarea pustiei de la râul Eufrat, pentru că vitele lor erau înmulțite în țara Galaadului."],[10,"În zilele lui Saul, au făcut război cu Hagrienii, care au căzut de mâna lor; și au locuit în corturile lor în toată țara de la est de Galaad."],[11,"Fiii lui Gad locuiau alături de ei în țara Basanului până la Saleca."],[12,"Ioel căpetenia, Şafam al doilea, Ianai şi Şafat în Basan."],[13,"Frații lor din casele părinților lor: Mihail, Meșulam, Șeba, Iorai, Iacan, Zia și Eber, șapte."],[14,"Aceștia au fost fiii lui Abihail, fiul lui Huri, fiul lui Iaroah, fiul lui Galaad, fiul lui Mihai, fiul lui Ieșisai, fiul lui Iahdo, fiul lui Buz;"],[15,"Ahi, fiul lui Abdiel, fiul lui Guni, căpetenia caselor părinților lor."],[16,"Ei locuiau în Galaad, în Basan, în cetățile lui și în toate pășunile Saronului, până la hotarele lor."],[17,"Toate acestea au fost înscrise după genealogii în zilele lui Iotam, împăratul lui Iuda, și în zilele lui Ieroboam, împăratul lui Israel."],[18,"Fiii lui Ruben, Gadiții și jumătate din seminția lui Manase, bărbați viteji, oameni în stare să poarte scule și sabie, pricepuți să tragă cu arcul și pricepuți la război, au fost patruzeci și patru de mii șapte sute șaizeci de oameni în stare să iasă la război."],[19,"Au făcut război cu Hagrienii, cu Ietur, cu Nafiș și cu Nodab."],[20,"Ei au fost ajutați împotriva lor și Hagriții au fost predați în mâinile lor și toți cei care erau cu ei; căci ei au strigat către Dumnezeu în luptă și el le-a răspuns pentru că și-au pus încrederea în El."],[21,"Şi-au luat vitele: din cămilele lor cincizeci de mii, din oi două sute cincizeci de mii, din măgari două mii şi din oameni o sută de mii."],[22,"Căci mulți au căzut uciși, pentru că războiul era de la Dumnezeu. Au locuit în locul lor până la captivitate."],[23,"Copiii din jumătatea seminției lui Manase locuiau în țară. Au crescut de la Basan la Baal Hermon, Senir și Muntele Hermon."],[24,"Aceștia au fost căpeteniile caselor părinților lor: Efer, Iși, Eliel, Azriel, Ieremia, Hodavia și Iahdiel – oameni puternici, viteji, oameni celebri, căpetenii ai caselor părinților lor."],[25,"Au păcătuit împotriva Dumnezeului părinţilor lor şi s-au prostituat după dumnezeii popoarelor ţării pe care Dumnezeu ia nimicit înaintea lor."],[26,"Astfel, Dumnezeul lui Israel a stârnit duhul lui Pul, împăratul Asiriei, și duhul lui Tilgat Pilneser, regele Asiriei, și i-a luat pe Rubeniți, pe Gadiți și pe jumătate din seminția lui Manase și i-a adus până în ziua de azi la Halah, Habor, Hara și la râul Gozan."]]],[6,[[1,"Fiii lui Levi: Gherșon, Chehat și Merari."],[2,"Fiii lui Chehat: Amram, Ițehar, Hebron și Uziel."],[3,"Fiii lui Amram: Aaron, Moise și Miriam. Fiii lui Aaron: Nadab, Abihu, Eleazar și Itamar."],[4,"Eleazar a născut pe Fineas, Fineas a născut pe Abișua,"],[5,"Abișua a devenit tatăl lui Bukki. Bukki a devenit tatăl lui Uzzi."],[6,"Uzi a născut pe Zerahia. Zerahia a născut pe Meraiot."],[7,"Meraiot a născut pe Amaria. Amaria a născut pe Ahitub."],[8,"Ahitub a născut pe Țadoc. Țadoc a născut pe Ahimaaț."],[9,"Ahimaaz a născut pe Azaria. Azaria a născut pe Iohanan."],[10,"Iohanan a născut pe Azaria, care a îndeplinit funcția de preot în casa pe care Solomon a zidit-o în Ierusalim."],[11,"Azaria a născut pe Amaria. Amaria a născut pe Ahitub."],[12,"Ahitub a născut pe Țadoc. Țadoc a născut pe Șalum."],[13,"Şalum a născut pe Hilchia. Hilchia a născut pe Azaria."],[14,"Azaria a născut pe Seraia. Seraia a născut pe Ioțadac."],[15,"Ioțadac a intrat în robie când Domnul a luat pe Iuda și Ierusalimul prin mâna lui Nebucadnețar."],[16,"Fiii lui Levi: Gherșom, Chehat și Merari."],[17,"Acestea sunt numele fiilor lui Gherșom: Libni și Șimei."],[18,"Fiii lui Chehat au fost Amram, Ițehar, Hebron și Uziel."],[19,"Fiii lui Merari: Mahli și Muși. Acestea sunt familiile leviților, după casele părinților lor."],[20,"Din Gherșom: Libni, fiul său, Iahat, fiul său, Zima, fiul său,"],[21,"Ioah, fiul său, Iddo, fiul său, Zerah, fiul său, și Ieatherai, fiul său."],[22,"Fiii lui Chehat: fiul său Aminadab, fiul său Core, fiul său Asir,"],[23,"Elcana, fiul său, Ebiasaf, fiul său, Asir, fiul său,"],[24,"Tahat, fiul său, Uriel, fiul său, Ozia, fiul său, și Saul, fiul său."],[25,"Fiii lui Elcana: Amasai și Ahimot."],[26,"Cât despre Elcana, fiii lui Elcana: Țofai, fiul său, Nahat, fiul său,"],[27,"Eliab, fiul său, Ieroham, fiul său, și Elcana, fiul său."],[28,"Fiii lui Samuel: primul născut, Ioel, și al doilea, Abia."],[29,"Fiii lui Merari: Mahli, Libni, fiul său, Șimei, fiul său, Uza, fiul său,"],[30,"Şimea, fiul său, Hagia, fiul său, Asaia, fiul său."],[31,"Aceștia sunt cei pe care David i-a pus peste slujba cântărilor în casa Domnului, după ce chivotul s-a oprit acolo."],[32,"Au slujit cu cântări înaintea cortului Cortului Întâlnirii până când Solomon a zidit Casa Domnului în Ierusalim. Ei și-au îndeplinit sarcinile funcției lor conform ordinului lor."],[33,"Aceștia sunt cei care au slujit și fiii lor. Dintre fiii Chehatiților: cântărețul Heman, fiul lui Ioel, fiul lui Samuel,"],[34,"fiul lui Elcana, fiul lui Ieroham, fiul lui Eliel, fiul lui Toah,"],[35,"fiul lui Țuf, fiul lui Elcana, fiul lui Mahat, fiul lui Amasai,"],[36,"fiul lui Elcana, fiul lui Ioel, fiul lui Azaria, fiul lui Țefania,"],[37,"fiul lui Tahat, fiul lui Asir, fiul lui Ebiasaf, fiul lui Core,"],[38,"fiul lui Ițehar, fiul lui Chehat, fiul lui Levi, fiul lui Israel."],[39,"Fratele său Asaf, care stătea de-a dreapta lui, chiar Asaf, fiul lui Berechia, fiul lui Şimea,"],[40,"fiul lui Mihai, fiul lui Baaseia, fiul lui Malchia,"],[41,"fiul lui Etni, fiul lui Zerah, fiul lui Adaia,"],[42,"fiul lui Etan, fiul lui Zima, fiul lui Șimei,"],[43,"fiul lui Iahat, fiul lui Gherșom, fiul lui Levi."],[44,"La stânga, frații lor, fiii lui Merari: Etan, fiul lui Chiși, fiul lui Abdi, fiul lui Maluch,"],[45,"fiul lui Haşabia, fiul lui Amazia, fiul lui Hilchia,"],[46,"fiul lui Amzi, ​​fiul lui Bani, fiul lui Șemer,"],[47,"fiul lui Mahli, fiul lui Muși, fiul lui Merari, fiul lui Levi."],[48,"Frații lor, leviții, au fost numiți pentru toată slujba cortului casei lui Dumnezeu."],[49,"Dar Aaron și fiii săi au adus pe altarul arderilor de tot și pe altarul tămâierii, pentru toată lucrarea locașului preasfânt și pentru a face ispășire pentru Israel, după tot ce poruncise Moise, robul lui Dumnezeu."],[50,"Aceștia sunt fiii lui Aaron: Eleazar, fiul său, Fineas, fiul său, Abișua, fiul său,"],[51,"Buki, fiul său, Uzi, fiul său, Zerahia, fiul său,"],[52,"Meraiot, fiul său, Amaria, fiul său, Ahitub, fiul său,"],[53,"Țadoc, fiul său, și Ahimaaț, fiul său."],[54,"Acestea sunt locurile lor de locuit, după taberele lor în hotarele lor: pentru fiii lui Aaron, din familiile Chehatiților (căci al lor a fost primul lot),"],[55,"lor le-au dat Hebronul în țara lui Iuda și pășunile lui din jurul lui;"],[56,"dar câmpurile cetăţii şi satele ei le-au dat lui Caleb, fiul lui Iefune."],[57,"Fiilor lui Aaron le-au dat cetățile de refugiu: Hebron, Libna și pășunile lui, Jattir, Eștemoa cu pășunile lui,"],[58,"Hilen cu pășunile lui, Debir cu pășunile sale,"],[59,"Așan cu pășunile lui și Bet-Șemeș cu pășunile lui;"],[60,"și din seminția lui Beniamin, Gheba cu pășunile lui, Alemetul cu pășunile lui și Anatotul cu pășunile lui. Toate cetățile lor, în toate familiile lor, erau treisprezece orașe."],[61,"Ceilalți fii ai lui Chehat li s-au dat prin sorți, din familia tribului, din jumătatea seminției, jumătatea lui Manase, zece cetăți."],[62,"Fiilor lui Gherșom, după familiile lor, din seminția lui Isahar și din seminția lui Așer și din seminția lui Neftali și din seminția lui Manase din Basan, treisprezece cetăți."],[63,"Fiilor lui Merari li s-au dat la sorți, după familiile lor, din seminția lui Ruben, din seminția lui Gad și din seminția lui Zabulon, douăsprezece cetăți."],[64,"Copiii lui Israel au dat leviților cetățile cu pășunile lor."],[65,"Ei au dat prin sorți din seminția copiilor lui Iuda și din seminția copiilor lui Simeon și din seminția copiilor lui Beniamin, aceste cetăți care sunt pomenite pe nume."],[66,"Unele dintre familiile fiilor lui Chehat aveau cetăți din granițele lor din seminția lui Efraim."],[67,"Le-au dat cetățile de refugiu, Sihemul în muntele lui Efraim cu pășunile lui și Ghezer cu pășunile lui,"],[68,"Iocmeam cu pășunile lui, Bet-Horon cu pășunile sale,"],[69,"Aialon cu pășunile lui, Gath Rimon cu pășunile lui;"],[70,"și din jumătatea tribului lui Manase, Aner cu pășunile lui și Bileam cu pășunile lui, pentru restul familiei fiilor lui Chehat."],[71,"Fiilor lui Gherșom, din familia jumătății de seminție a lui Manase, au fost date Golan în Basan cu pășunile lui și Aștarot cu pășunile lui;"],[72,"și din seminția lui Isahar, Chedes cu pășunile lui, Daberat cu pășunile lui,"],[73,"Ramot cu pășunile lui și Anem cu pășunile lui;"],[74,"și din seminția lui Așer, Mashal cu pășunile lui, Abdon cu pășunile lui,"],[75,"Hucoc cu pășunile lui și Rehob cu pășunile lui;"],[76,"și din seminția lui Neftali, Chedes din Galileea cu pășunile lui, Hammon cu pășunile lui și Chiriataim cu pășunile lui."],[77,"Ceilalți leviți, fiilor lui Merari, li s-au dat, din seminția lui Zabulon, Rimono cu pășunile lui și Taborul cu pășunile lui;"],[78,"și dincolo de Iordan, la Ierihon, pe partea de est a Iordanului, li s-au dat din seminția lui Ruben: Bețer în pustiu cu pășunile lui, Iahza cu pășunile lui,"],[79,"Chedemot cu pășunile lui și Mefaat cu pășunile lui;"],[80,"și din seminția lui Gad, Ramot în Galaad cu pășunile lui, Mahanaim cu pășunile lui,"],[81,"Hesbon cu pășunile lui și Iazer cu pășunile lui."]]],[7,[[1,"Dintre fiii lui Isahar: Tola, Pua, Iașub și Șimron, patru."],[2,"Fiii lui Tola: Uzi, Refaia, Ieriel, Iahmai, Ibsam și Șemuel, căpeteniile caselor lor părintești, din Tola; oameni puternici viteji în generațiile lor. Numărul lor în zilele lui David a fost douăzeci și două de mii șase sute."],[3,"Fiul lui Uzi: Izrahia. Fiii lui Izrahia: Mihail, Obadia, Ioel și Ishia, cinci; toți bărbați șefi."],[4,"Cu ei, după generațiile lor, după casele părinților lor, erau trupe de oști pentru război, treizeci și șase de mii; căci aveau multe soţii şi fii."],[5,"Frații lor din toate familiile lui Isahar, oameni viteji și viteji, înscriși după genealogie, au fost optzeci și șapte de mii."],[6,"Fiii lui Beniamin: Bela, Becher și Iediael, trei."],[7,"Fiii lui Bela: Ezbon, Uzi, Uziel, Ierimot și Iri, cinci; șefi ai caselor părintești, viteji și viteji; și au fost înscriși după genealogie douăzeci și două de mii treizeci și patru."],[8,"Fiii lui Becher: Zemira, Ioas, Eliezer, Elioenai, Omri, Ieremot, Abia, Anatot și Alemet. Toți aceștia au fost fiii lui Becher."],[9,"Ei au fost înscriși după genealogie, după generațiile lor, căpetenii casei părinților lor, viteji viteji, douăzeci de mii două sute."],[10,"Fiul lui Iediael: Bilhan. Fiii lui Bilhan: Ieuș, Beniamin, Ehud, Chenaana, Zetan, Tarsis și Ahișahar."],[11,"Toți aceștia erau fiii lui Iediael, după capii casei părinților lor, bărbați viteji, șaptesprezece mii două sute, care puteau să iasă în oști la război."],[12,"La fel au fost Şupim, Huppim, fiii lui Ir, Huşim şi fiii lui Aer."],[13,"Fiii lui Neftali: Iahziel, Guni, Iezer, Șalum și fiii lui Bilha."],[14,"Fiii lui Manase: Asriel, pe care l-a născut concubina lui, aramitea. Ea a născut pe Machir, tatăl lui Galaad."],[15,"Machir și-a luat o soție a lui Huppim și Shuppim, a căror soră o chema Maaca. Numele celui de-al doilea era Țelofehad; şi Ţelofehad a avut fete."],[16,"Maaca, soția lui Macir, a născut un fiu, și i-a pus numele Pereș. Numele fratelui său era Şereş; și fiii lui au fost Ulam și Rakem."],[17,"Fiii lui Ulam: Bedan. Aceștia au fost fiii lui Galaad, fiul lui Machir, fiul lui Manase."],[18,"Sora lui Hammolechet i-a născut pe Ișhod, Abiezer și Mahla."],[19,"Fiii lui Șemida au fost Ahian, Sihem, Lichi și Aniam."],[20,"Fiii lui Efraim: Șutela, fiul său Bered, fiul său Tahat, fiul său Eleada, fiul său Tahat,"],[21,"Zabad, fiul său, Șutela, fiul său, Ezer și Elead, pe care bărbații din Gat, născuți în țară, i-au ucis, pentru că s-au coborât să-și ia vitele."],[22,"Efraim, tatăl lor, a jelit multe zile și frații lui au venit să-l mângâie."],[23,"El a intrat la soția sa, care a rămas însărcinată și a născut un fiu și i-a pus numele Beria, pentru că era necaz cu casa lui."],[24,"Fiica lui a fost Şeera, care a zidit Bet-Horon cea de jos şi cea de sus, şi Uzen-Şeera."],[25,"Refa era fiul său, Reșef fiul său, Telah fiul său, Tahan fiul său,"],[26,"Ladan, fiul său, Amihud, fiul său, Elisama, fiul său,"],[27,"fiul său Nun și fiul său Iosua."],[28,"Proprietățile și așezările lor erau Betel și cetățile lui, și spre est Naaran și spre vest Ghezer cu cetățile lui; Şi Sihemul şi cetăţile lui, până la Aza şi cetăţile lui;"],[29,"și lângă hotarele fiilor lui Manase, Bet-Șean și cetățile lui, Taanac și cetățile lui, Meghido și cetățile lui și Dor și cetățile lui. În acestea locuiau copiii lui Iosif, fiul lui Israel."],[30,"Fiii lui Așer: Imna, Ișva, Ișvi și Beria. Serah era sora lor."],[31,"Fiii lui Beria: Heber și Malchiel, care a fost tatăl lui Birțait."],[32,"Heber a născut pe Iaflet, pe Şomer, pe Hotam şi pe sora lor Şua."],[33,"Fiii lui Iaflet: Pasach, Bimhal și Așvat. Aceștia sunt copiii lui Iaflet."],[34,"Fiii lui Șemer: Ahi, Rohga, Iehuba și Aram."],[35,"Fiii lui Helem, fratele său: Țofa, Imna, Șeleș și Amal."],[36,"Fiii lui Țofa: Suah, Harnefer, Shual, Beri, Imrah,"],[37,"Bezer, Hod, Shama, Shilshah, Itran și Beera."],[38,"Fiii lui Ieter: Iefune, Pispa și Ara."],[39,"Fiii lui Ulla: Arah, Haniel și Rizia."],[40,"Toți aceștia erau fiii lui Așer, șefi ai caselor părintești, oameni aleși și viteji, căpetenii prinților. Numărul dintre ei enumerați după genealogie pentru serviciul în război a fost de douăzeci și șase de mii de oameni."]]],[8,[[1,"Beniamin a născut pe Bela, întâiul său născut, pe Așbel pe al doilea, pe Ahara pe al treilea,"],[2,"Nohah al patrulea și Rapha al cincilea."],[3,"Bela a avut fii: Adar, Ghera, Abihud,"],[4,"Abișua, Naaman, Ahoah,"],[5,"Ghera, Şefufan şi Huram."],[6,"Aceștia sunt fiii lui Ehud. Iată căpeteniile familiilor părintești ai locuitorilor din Gheba, care au fost duși în robie la Manahat:"],[7,"Naaman, Ahija și Ghera, care i-au dus în robie; și a născut pe Uza și pe Ahihud."],[8,"Șaharaim a născut copii în câmpul Moabului, după ce i-a alungat. Hușim și Baara erau soțiile lui."],[9,"Prin soția sa Hodes, el a născut pe Iobab, pe Țibia, pe Meșa, pe Malcam,"],[10,"Jeuz, Shachia și Mirmah. Aceștia erau fiii săi, șefii casei părinților."],[11,"Prin Hușim, el a devenit tatăl lui Abitub și Elpaal."],[12,"Fiii lui Elpaal: Eber, Mișam și Semed, care au zidit Ono și Lod, cu cetățile lui;"],[13,"și Beria și Șema, care erau șefii casei de tată ai locuitorilor din Aialon, care i-au pus pe fugă pe locuitorii Gatului;"],[14,"și Ahio, Șașak, Ieremot,"],[15,"Zebadia, Arad, Eder,"],[16,"Mihail, Ispa, Ioha, fiii lui Beria,"],[17,"Zebadia, Meșulam, Hizki, Heber,"],[18,"Ismerai, Izlia, Iobab, fiii lui Elpaal,"],[19,"Jakim, Zichri, Zabdi,"],[20,"Elienai, Zillethai, Eliel,"],[21,"Adaia, Beraia, Șimrat, fiii lui Șimei,"],[22,"Ishpan, Eber, Eliel,"],[23,"Abdon, Zichri, Hanan,"],[24,"Hanania, Elam, Anthothia,"],[25,"Ifdeia, Penuel, fiii lui Șașac,"],[26,"Şamserai, Şeharia, Athalia,"],[27,"Iareșia, Ilie, Zicri și fiii lui Ieroham."],[28,"Aceștia au fost șefii de familie ai taților în generațiile lor, bărbați căpetenii. Aceștia locuiau în Ierusalim."],[29,"Tatăl lui Gabaon, a cărui soție se numea Maaca, locuia în Gabaon"],[30,"cu fiul său întâi născut Abdon, Țur, Chiș, Baal, Nadab,"],[31,"Ghedor, Ahio, Zecher,"],[32,"și Miclot, care a născut pe Șimea. Ei locuiau și cu familiile lor în Ierusalim, lângă rudele lor."],[33,"Ner a fost tatăl lui Chiș. Chiș a născut pe Saul. Saul a născut pe Ionatan, pe Malchișua, pe Abinadab și pe Eșbaal."],[34,"Fiul lui Ionatan a fost Merib-baal. Merib-baal a născut pe Mica."],[35,"Fiii lui Mica: Piton, Melec, Tarea și Ahaz."],[36,"Ahaz a născut pe Ioada. Ioada a născut pe Alemet, pe Azmavet și pe Zimri. Zimri a născut pe Moza."],[37,"Moza a devenit tatăl lui Binea. Rafa era fiul său, Eleasa fiul său și Azel fiul său."],[38,"Azel a avut șase fii, ale căror nume sunt acestea: Azrikam, Bocheru, Ismael, Șearia, Obadia și Hanan. Toți aceștia au fost fiii lui Azel."],[39,"Fiii lui Eșec, fratele său: Ulam, întâiul său născut, Ieuș, al doilea, și Elifelet, al treilea."],[40,"Fiii lui Ulam au fost oameni viteji, arcași și au avut mulți fii și nepoți, o sută cincizeci. Toți aceștia erau din fiii lui Beniamin."]]],[9,[[1,"Deci tot Israelul a fost înscris după genealogii; și iată, ele sunt scrise în cartea împăraților lui Israel. Iuda a fost dus captiv în Babilon pentru neascultarea lor."],[2,"Primii locuitori care au locuit în moșiile lor în cetățile lor au fost Israel, preoții, leviții și slujitorii templului."],[3,"În Ierusalim, locuiau din copiii lui Iuda, din fiii lui Beniamin și din copiii lui Efraim și Manase:"],[4,"Uthai, fiul lui Amihud, fiul lui Omri, fiul lui Imri, fiul lui Bani, din fiii lui Pereț, fiul lui Iuda."],[5,"Dintre șiloniți: Asaia, întâiul născut și fiii săi."],[6,"Dintre fiii lui Zerah: Ieuel și frații lor, șase sute nouăzeci."],[7,"Dintre fiii lui Beniamin: Salu, fiul lui Meșulam, fiul lui Hodavia, fiul lui Hassenua;"],[8,"și Ibneia, fiul lui Ieroham, și Ela, fiul lui Uzi, fiul lui Micri; şi Meşulam, fiul lui Şefatia, fiul lui Reuel, fiul lui Ibnia;"],[9,"și frații lor, după generațiile lor, nouă sute cincizeci și șase. Toți acești bărbați erau șefi de case ale taților, după casele părinților lor."],[10,"Dintre preoți: Iedaia, Ioiarib, Iachin,"],[11,"și Azaria, fiul lui Hilchia, fiul lui Meșulam, fiul lui Țadoc, fiul lui Meraiot, fiul lui Ahitub, conducătorul casei lui Dumnezeu;"],[12,"și Adaia, fiul lui Ieroham, fiul lui Pașhur, fiul lui Malchia; și Maasai, fiul lui Adiel, fiul lui Iahzera, fiul lui Meșulam, fiul lui Meșilemit, fiul lui Imer;"],[13,"și frații lor, căpeteniile casei lor, o mie șapte sute șaizeci; erau oameni foarte capabili pentru lucrarea slujirii casei lui Dumnezeu."],[14,"Dintre leviţi: Şemaia, fiul lui Haşub, fiul lui Azricam, fiul lui Haşabia, din fiii lui Merari;"],[15,"și Bakbacar, Hereș, Galal și Matania, fiul lui Mica, fiul lui Zicri, fiul lui Asaf,"],[16,"şi Obadia, fiul lui Şemaia, fiul lui Galal, fiul lui Iedutun; şi Berechia, fiul lui Asa, fiul lui Elcana, care locuia în satele netofatiţilor."],[17,"Portarii: Șalum, Akub, Talmon, Ahiman și frații lor (Șalum era căpetenia),"],[18,"care a slujit înainte la poarta împăratului spre răsărit. Ei erau paznicii taberei fiilor lui Levi."],[19,"Şalum era fiul lui Core, fiul lui Ebiasaf, fiul lui Core, şi fraţii lui, din casa tatălui său, Corehiţii, erau peste lucrarea slujirii, păzitorii pragurilor cortului. Părinții lor fuseseră peste tabăra Domnului, păzitori ai intrării."],[20,"Fineas, fiul lui Eleazar, era stăpân peste ei în trecut, iar Domnul era cu el."],[21,"Zaharia, fiul lui Meşelemia, era portarul uşii Cortului Întâlnirii."],[22,"Toți aceștia care au fost aleși să fie paznici în praguri au fost două sute doisprezece. Aceștia au fost enumerați după genealogie în satele lor, pe care David și văzătorul Samuel i-au rânduit în slujba lor de încredere."],[23,"Deci, ei și copiii lor aveau supravegherea porților Casei Domnului, chiar a casei cortului, ca străji."],[24,"Pe cele patru laturi erau paznicii, spre est, vest, nord si sud."],[25,"Frații lor, în satele lor, trebuiau să vină din când în când la fiecare șapte zile să fie cu ei,"],[26,"căci cei patru căpetenii a porții, care erau leviți, erau într-o slujbă de încredere și erau peste odăile și vistieriile din Casa lui Dumnezeu."],[27,"Ei au stat în preajma casei lui Dumnezeu, pentru că aceasta era datoria lor; și era de datoria lor să o deschidă dimineață de dimineață."],[28,"Unii dintre ei se ocupau de vasele de serviciu, căci acestea erau aduse după număr, iar acestea erau scoase după număr."],[29,"Unii dintre ei au fost însărcinați peste mobilier și peste toate vasele sanctuarului, peste făina cea mai bună, vinul, untdelemnul, tămâia și mirodeniile."],[30,"Unii dintre fiii preoților au pregătit amestecul mirodenilor."],[31,"Matitia, unul dintre leviți, care era întâiul născut al lui Șalum, Coreitul, avea slujba de încredere asupra lucrurilor care erau coapte în tigaie."],[32,"Unii dintre frații lor, dintre fiii Chehatiților, erau peste pâinea arătării, ca să o pregătească în fiecare Sabat."],[33,"Aceștia sunt cântăreții, șefii casei părintești ai leviților, care locuiau în camere și erau liberi de alte slujbe, pentru că erau angajați în munca lor zi și noapte."],[34,"Aceștia au fost șefii caselor părintești ale leviților, în neamurile lor, bărbați căpetenii. Ei locuiau la Ierusalim."],[35,"Ieiel, tatăl lui Gabaon, a cărui soție se numea Maaca, locuia în Gabaon."],[36,"Fiul său întâi născut a fost Abdon, apoi Țur, Chiș, Baal, Ner, Nadab,"],[37,"Ghedor, Ahio, Zaharia și Miclot."],[38,"Miclot a născut pe Șimeam. De asemenea, locuiau cu rudele lor în Ierusalim, lângă rudele lor."],[39,"Ner a fost tatăl lui Chiș. Chiș a născut pe Saul. Saul a născut pe Ionatan, pe Malchișua, pe Abinadab și pe Eșbaal."],[40,"Fiul lui Ionatan a fost Merib-baal. Merib-baal a născut pe Mica."],[41,"Fiii lui Mica: Piton, Melec, Tahrea și Ahaz."],[42,"Ahaz a născut pe Iara. Iara a născut pe Alemet, pe Azmavet și pe Zimri. Zimri a născut pe Moza."],[43,"Moza a născut pe Binea, pe Refaia, fiul său, Eleasa, fiul său, și Azel, fiul său."],[44,"Azel a avut șase fii, ale căror nume sunt Azrikam, Bocheru, Ismael, Șearia, Obadia și Hanan. Aceștia au fost fiii lui Azel."]]],[10,[[1,"Filistenii au luptat împotriva lui Israel; și bărbații lui Israel au fugit dinaintea filistenilor și au căzut uciși pe muntele Ghilboa."],[2,"Filistenii l-au urmat pe Saul și pe fiii lui; și filistenii au ucis pe Ionatan, Abinadab și Malchișua, fiii lui Saul."],[3,"Bătălia a fost grea împotriva lui Saul și arcașii l-au ajuns; și a fost întristat din cauza arcașilor."],[4,"Atunci Saul i-a zis purtătorului său de arme: „Scoate-ți sabia și străpunge-mă cu ea, ca să nu vină acești netăiați împrejur și să mă batjocorească.”"],[5,"Când purtătorul său de armuri a văzut că Saul era mort, și el a căzut pe sabie și a murit."],[6,"Deci Saul a murit împreună cu cei trei fii ai săi; și toată casa lui a murit împreună."],[7,"Când toți bărbații lui Israel care erau în vale au văzut că au fugit și că Saul și fiii lui erau morți, și-au părăsit cetățile și au fugit; şi filistenii au venit şi au locuit în ei."],[8,"A doua zi, când filistenii au venit să dezbrace pe cei uciși, l-au găsit pe Saul și pe fiii lui căzuți pe muntele Ghilboa."],[9,"L-au dezbrăcat și i-au luat capul și armura, apoi au trimis în țara filistenilor de jur împrejur să ducă vestea idolilor lor și poporului."],[10,"I-au pus armura în casa zeilor lor și i-au prins capul în casa lui Dagon."],[11,"Când tot Iabes Galaad a auzit tot ce i-au făcut filistenii lui Saul,"],[12,"toți vitejii s-au sculat și au luat trupul lui Saul și trupurile fiilor săi și le-au adus la Iabeș și le-au îngropat oasele sub stejarul din Iabeș și au postit șapte zile."],[13,"Deci Saul a murit pentru greșeala sa pe care a săvârșit-o împotriva Domnului, din cauza cuvântului Domnului, pe care nu l-a ținut, și pentru că a cerut sfatul unuia care avea un duh cunoscut să-l întrebe:"],[14,"și nu l-a întrebat pe Domnul. De aceea l-a ucis și a predat împărăția lui David, fiul lui Isai."]]],[11,[[1,"Atunci tot Israelul s-a adunat la David la Hebron, zicând: „Iată, noi suntem oasele și carnea voastră."],[2,"În vremuri trecute, chiar și când Saul era rege, tu ai fost cel care ai condus și a adus în Israel. Domnul Dumnezeul tău ți-a spus: „Tu vei fi păstorul poporului meu Israel și vei fi căpetenie peste poporul meu Israel.”"],[3,"Deci toți bătrânii lui Israel au venit la rege la Hebron; și David a făcut un legământ cu ei la Hebron, înaintea Domnului. L-au uns pe David rege peste Israel, după cuvântul Domnului de la Samuel."],[4,"David și tot Israelul s-au dus la Ierusalim (numit și Iebus); și iebusiții, locuitorii țării, erau acolo."],[5,"Locuitorii din Iebus i-au spus lui David: „Nu vei intra aici!” Cu toate acestea, David a luat fortăreața Sionului. Același este și orașul lui David."],[6,"David spusese: „Cine va lovi primul pe iebusiți va fi căpetenia și căpetenia”. Ioab, fiul Țeruiei, a urcat primul și a fost pus căpetenie."],[7,"David locuia în fortăreață; de aceea au numit-o cetatea lui David."],[8,"El a construit orașul de jur împrejur, de la Millo până și în jur; şi Ioab a reparat restul cetăţii."],[9,"David era din ce în ce mai mare, căci Domnul armatelor era cu el."],[10,"Iată că aceștia sunt căpeteniile puternicilor pe care i-a avut David, care s-au arătat puternici împreună cu el în împărăția lui, împreună cu tot Israelul, ca să-l facă împărat, după cuvântul Domnului cu privire la Israel."],[11,"Acesta este numărul bărbaților puternici pe care i-a avut David: Iașobeam, fiul unui Hahmonit, căpetenia celor treizeci; și-a ridicat sulița împotriva a trei sute și i-a ucis deodată."],[12,"După el a fost Eleazar, fiul lui Dodo, Ahohitul, care era unul dintre cei trei viteji."],[13,"El a fost cu David la Pasdamim și acolo s-au adunat filistenii la luptă, unde era un teren plin de orz; iar poporul a fugit dinaintea filistenilor."],[14,"Au stat în mijlocul complotului, l-au apărat și i-au ucis pe filisteni; și Domnul i-a mântuit printr-o mare biruință."],[15,"Trei dintre cei treizeci de bărbați de căpetenie au coborât la stâncă la David, în peștera lui Adulam; iar armata filistenilor a tăbărât în ​​valea Refaim."],[16,"David era atunci în fortăreață, iar garnizoana filistenilor era în Betleem în vremea aceea."],[17,"David a tânjit și a zis: „O, dacă mi-ar da cineva să beau apă din fântâna Betleem, care este lângă poartă!”"],[18,"Cei trei au spart oastea filistenilor și au scos apă din fântâna Betleemului care era lângă poartă, au luat-o și i-au adus-o lui David; dar David nu a vrut să bea nimic din ea, ci a turnat-o Domnului,"],[19,"și a zis: „Dumnezeul meu ferește-mă să fac asta! Să beau oare sângele acestor oameni care și-au pus viața în primejdie?” Căci și-au riscat viața ca să-l aducă. De aceea nu l-a băut. Cei trei oameni puternici au făcut aceste lucruri."],[20,"Abişai, fratele lui Ioab, era căpetenia celor trei; pentru că și-a ridicat sulița împotriva a trei sute și i-a omorât și a avut un nume printre cei trei."],[21,"Dintre cei trei, el a fost mai onorabil decât cei doi și a fost pus căpitanul lor; cu toate acestea, el nu a fost inclus în cei trei."],[22,"Benaia, fiul lui Iehoiada, fiul unui bărbat viteaz din Kabzeel, care făcuse fapte mărețe, a ucis pe cei doi fii ai lui Ariel din Moab. De asemenea, a coborât și a ucis un leu în mijlocul unei gropi într-o zi cu zăpadă."],[23,"A ucis un egiptean, un om de statură mare, înalt de cinci coți. În mâna egipteanului era o suliță ca o bârnă de țesător; și s-a pogorât la el cu un toiag, a smuls sulița din mâna egipteanului și l-a omorât cu sulița lui."],[24,"Benaia, fiul lui Iehoiada, a făcut aceste lucruri și a avut un nume printre cei trei viteji."],[25,"Iată, el a fost mai cinstit decât cei treizeci, dar nu a ajuns la cei trei; și David l-a pus peste pază."],[26,"Oamenii puternici ai armatei includ și Asael, fratele lui Ioab, Elhanan, fiul lui Dodo din Betleem,"],[27,"Shammoth Haroritul, Helez Pelonitul,"],[28,"Ira, fiul lui Ikeș, tecoitul, Abiezer, anatotit,"],[29,"Sibecai Husatitul, Ilai Ahohitul,"],[30,"Maharai, netofatitul, Heled, fiul lui Baana, netofatitul,"],[31,"Ithai, fiul lui Ribai, din Ghibea, din fiii lui Beniamin, Benaia, piratonitul,"],[32,"Hurai din pârâurile lui Gaaș, Abiel Arbathitul,"],[33,"Azmavet Baharumitul, Eliahba Şaalbonitul,"],[34,"fiii lui Hashem, Gizonitul, Ionatan, fiul lui Shaghee Hararitul,"],[35,"Ahiam, fiul lui Sacar Hararitul, Elifal, fiul lui Ur,"],[36,"Hefer Mecheratitul, Ahia Pelonitul,"],[37,"Heţro, Carmelitul, Naarai, fiul lui Ezbai,"],[38,"Ioel, fratele lui Natan, Mibhar, fiul lui Hagri,"],[39,"Țelec, amonitul, Naharai, beretul (purtatorul de armuri al lui Ioab, fiul lui Țeruia),"],[40,"Ira Itritul, Gareb Itritul,"],[41,"Urie hetitul, Zabad, fiul lui Ahlai,"],[42,"Adina, fiul lui Șiza Rubenitul (un căpetenie al rubeniților), și treizeci cu el,"],[43,"Hanan, fiul lui Maaca, Iosafat mitnitul,"],[44,"Uzia, Așteratul, Șama și Ieiel, fiii lui Hotam, Aroeritul,"],[45,"Iediael, fiul lui Șimri, și Ioha, fratele său, tizitul,"],[46,"Eliel Mahavitul și Ieribai și Iosavia, fiii lui Elnaam și Itma moabitul,"],[47,"Eliel, Obed și Iaasiel Mezobaitul."]]],[12,[[1,"Aceștia sunt cei care au venit la David la Țiclag, când el era fugar de Saul, fiul lui Chiș. Ei erau printre oamenii puternici, ajutoarele lui în război."],[2,"Erau înarmați cu arcuri și puteau folosi atât mâna dreaptă, cât și mâna stângă la aruncarea pietrelor și la tragerea cu săgeți din arc. Erau din rudele lui Saul din seminția lui Beniamin."],[3,"Căpetenia a fost Ahiezer, apoi Ioas, fiii lui Șemaa ghibeatitul; Jeziel și Pelet, fiii lui Azmavet; Beracah; Iehu, Anatotitul;"],[4,"Ismaia gabaonitul, un om puternic dintre cei treizeci și un conducător al celor treizeci; Ieremia; Iahaziel; Iohanan; Iozabad Ghederatitul;"],[5,"Eluzai; Ierimot; Bealiah; Shemaria; Şefatia Harufitul;"],[6,"Elcana, Isia, Azarel, Ioezer și Iașobeam, Coreiții;"],[7,"și Ioela și Zebadia, fiii lui Ieroham din Ghedor."],[8,"Unii gadiți s-au alăturat lui David în fortăreața din pustie, oameni puternici și viteji, oameni pregătiți pentru război, care puteau mânui scutul și sulița; ale căror fețe erau ca fețele de lei și erau la fel de iute ca gazelele de pe munți;"],[9,"Ezer, căpetenia, Obadia, al doilea, Eliab, al treilea,"],[10,"Mișmana al patrulea, Ieremia al cincilea,"],[11,"Attai al șaselea, Eliel al șaptelea,"],[12,"Iohanan al optulea, Elzabad al nouălea,"],[13,"Ieremia al zecelea și Macbannai al unsprezecelea."],[14,"Aceștia dintre fiii lui Gad erau căpetenii armatei. Cel mai mic era egal cu o sută, iar cel mai mare cu o mie."],[15,"Aceștia sunt cei care au trecut Iordanul în prima lună, când acesta și-a revărsat toate malurile; şi i-au dat la fugă pe toţi cei ce locuiau în văi, atât spre răsărit, cât şi spre apus."],[16,"Unii dintre copiii lui Beniamin și Iuda au venit în fortăreață la David."],[17,"David a ieșit în întâmpinarea lor și le-a răspuns: „Dacă ați venit cu pace la mine ca să mă ajutați, inima mea va fi unită cu voi; dar dacă ați venit să mă trădeți vrăjmașilor mei, pentru că nu este nicio greșeală în mâinile mele, Dumnezeul părinților noștri să vadă aceasta și să o mustre.”"],[18,"Atunci Duhul a venit peste Amasai, care era căpetenia celor treizeci, și a zis: „Noi suntem ai tăi, David, și de partea ta, fiul lui Isai. Pace, pace ție și pace ajutătorilor tăi, căci Dumnezeul tău te ajută.” Atunci David i-a primit și i-a pus căpetenii trupei."],[19,"Unii din Manase s-au alăturat lui David, când a venit cu filistenii împotriva lui Saul, la luptă, dar ei nu i-au ajutat, căci stăpânii filistenilor l-au dat afară după ce s-au sfătuit, zicând: „El va părăsi stăpânului său, Saul, pentru a ne pune în pericol”."],[20,"Pe când mergea la Țiclag, i s-au alăturat unii din Manase: Adna, Iozabad, Iediael, Mihail, Iozabad, Elihu și Țiletai, căpetenii de mii care erau din Manase."],[21,"Ei l-au ajutat pe David împotriva trupei de răpitori, pentru că toți erau oameni viteji și viteji și căpetenii în armată."],[22,"Căci din zi în zi veneau oameni la David să-l ajute, până când a fost o oaste mare, ca oastea lui Dumnezeu."],[23,"Acestea sunt numărul căpeteniilor celor înarmați pentru război, care au venit la David la Hebron pentru a-i întoarce împărăția lui Saul, după cuvântul Domnului."],[24,"Fiii lui Iuda, care purtau scut și suliță, erau șase mii opt sute, înarmați pentru război."],[25,"Din fiii lui Simeon, bărbați viteji pentru război: șapte mii o sută."],[26,"Din fiii lui Levi: patru mii șase sute."],[27,"Iehoiada era conducătorul casei lui Aaron; și cu el erau trei mii șapte sute,"],[28,"și Țadoc, un tânăr viteaz, și douăzeci și doi de căpetenii din casa tatălui său."],[29,"Dintre copiii lui Beniamin, rudele lui Saul: trei mii, căci până atunci, cea mai mare parte dintre ei își păstraseră credința față de casa lui Saul."],[30,"Din fiii lui Efraim: douăzeci de mii opt sute, viteji și viteji, oameni celebri în casele părinților lor."],[31,"Din jumătatea seminției lui Manase: optsprezece mii, care erau pomeniți pe nume, ca să vină să facă rege pe David."],[32,"Dintre copiii lui Isahar, bărbați care înțelegeau vremurile, ca să știe ce trebuia să facă Israel, capetele lor erau două sute; și toți frații lor erau la porunca lor."],[33,"Din Zabulon, cei care puteau ieși în oștire, care puteau să pună în ordine lupta cu tot felul de instrumente de război: cincizeci de mii care puteau comanda și nu aveau inimă dublă."],[34,"din Neftali: o mie de căpetenii și cu ei treizeci și șapte de mii cu scut și suliță."],[35,"Din daniți care puteau aranja lupta: douăzeci și opt de mii șase sute."],[36,"Din Așer, cei care erau în stare să iasă în armată, care puteau aranja lupta: patruzeci de mii."],[37,"De cealaltă parte a Iordanului, din Rubeniți, Gadiți și din jumătatea tribului lui Manase, cu tot felul de instrumente de război pentru luptă: o sută douăzeci de mii."],[38,"Toți aceștia erau bărbați de război care puteau ordona echipa de luptă și au venit cu o inimă desăvârșită la Hebron pentru a-l face pe David împărat peste tot Israelul; și tot restul lui Israel au avut o singură inimă să-l facă rege pe David."],[39,"Ei au stat acolo cu David trei zile, mâncând și bând; căci fraţii lor le furnizaseră provizii."],[40,"Mai mult, cei care erau aproape de ei, până la Isahar, Zabulon și Neftali, aduceau pâine pe măgari, pe cămile, pe catâri și pe boi: provizii de făină, turte de smochine, ciorchini de stafide, vin, untdelemn, vite și oi din belșug; căci era bucurie în Israel."]]],[13,[[1,"David s-a sfătuit cu căpeteniile de mii și de sute, chiar și cu fiecare conducător."],[2,"David a zis întregii adunări a lui Israel: „Dacă vi se pare bine și dacă este de la Domnul Dumnezeul nostru, să trimitem pretutindeni veste fraților noștri care au mai rămas în toată țara lui Israel, cu care preoții și leviții sunt în cetățile lor cu pășuni, ca să se adune la noi."],[3,"De asemenea, să aducem din nou chivotul Dumnezeului nostru înapoi la noi, pentru că nu l-am căutat în zilele lui Saul.”"],[4,"Toată adunarea a spus că vor face așa, căci lucrul era drept în ochii întregului popor."],[5,"Deci David a adunat pe tot Israelul, de la râul Sihor al Egiptului până la intrarea Hamatului, ca să aducă chivotul lui Dumnezeu din Chiriat-Iearim."],[6,"David s-a suit cu tot Israelul la Baala, adică la Chiriat-Iearim, care aparținea lui Iuda, ca să ridice de acolo chivotul lui Dumnezeu DOMNUL care stă deasupra heruvimilor, care este chemat cu Numele."],[7,"Au cărat chivotul lui Dumnezeu pe o căruță nouă și l-au scos din casa lui Abinadab; iar Uzza și Ahio au condus căruța."],[8,"David și tot Israelul cântau înaintea lui Dumnezeu cu toată puterea lor, chiar cu cântece, cu harpe, cu instrumente cu coarde, cu tamburine, cu chimvale și cu trâmbițe."],[9,"Când au ajuns la aria lui Chidon, Uza și-a întins mâna ca să țină chivotul, căci boii se poticneau."],[10,"Mânia Domnului s-a aprins împotriva lui Uza și l-a lovit pentru că și-a pus mâna pe chivot; și acolo a murit înaintea lui Dumnezeu."],[11,"David a fost nemulțumit, pentru că Domnul izbucnise împotriva lui Uza. El a numit acel loc Perez Uzza, până astăzi."],[12,"David s-a temut de Dumnezeu în ziua aceea și a zis: „Cum pot să aduc chivotul lui Dumnezeu acasă la mine?”"],[13,"Deci David nu a mutat chivotul cu el în cetatea lui David, ci l-a dus deoparte în casa lui Obed-Edom Gatitul."],[14,"Chivotul lui Dumnezeu a rămas cu familia lui Obed-Edom în casa lui trei luni; și Domnul a binecuvântat casa lui Obed-Edom și tot ce avea el."]]],[14,[[1,"Hiram, regele Tirului, a trimis soli la David cu cedri, zidari și dulgheri, ca să-i construiască o casă."],[2,"David și-a dat seama că Domnul l-a întemeiat rege peste Israel, pentru că împărăția lui era foarte înălțată, de dragul poporului său Israel."],[3,"David și-a luat mai multe soții în Ierusalim și David a născut mai mulți fii și fiice."],[4,"Acestea sunt numele copiilor pe care i-a avut în Ierusalim: Șamua, Șobab, Natan, Solomon,"],[5,"Ibhar, Elishua, Elpelet,"],[6,"Nogah, Nepheg, Japhia,"],[7,"Elishama, Beeliada și Elifelet."],[8,"Când filistenii au auzit că David a fost uns rege peste tot Israelul, toți filistenii s-au suit să-l caute pe David; şi David a auzit de aceasta şi a ieşit împotriva lor."],[9,"Filistenii veniseră și făcuseră o raiune în valea Refaimului."],[10,"David a întrebat pe Dumnezeu și a zis: „Să mă urc împotriva filistenilor? Îi vei da în mâna mea?”"],[11,"Deci s-au urcat la Baal-Peraim și David i-a învins acolo. David a spus: „Dumnezeu mi-a zdrobit vrăjmașii cu mâna mea, ca niște ape care izbucnesc”. De aceea au pus numele locului acelui Baal-Perazim."],[12,"Și-au lăsat zeii acolo; și David a dat poruncă și au fost arși cu foc."],[13,"Filistenii au făcut un alt raid în vale."],[14,"David a întrebat din nou pe Dumnezeu; și Dumnezeu i-a zis: „Să nu te sui după ei. Întoarce-te de la ei și vino peste ei în fața dudului."],[15,"Când auzi zgomotul de marș în vârfurile dudului, atunci ieși la luptă; căci Dumnezeu a ieşit înaintea ta să lovească armata filistenilor”."],[16,"David a făcut cum ia poruncit Dumnezeu; şi au atacat oastea filistenilor de la Gabaon până la Ghezer."],[17,"Faima lui David s-a răspândit în toate țările; şi Domnul a adus frica de el peste toate neamurile."]]],[15,[[1,"David și-a făcut case în orașul lui David; și a pregătit un loc pentru chivotul lui Dumnezeu și a ridicat un cort pentru ea."],[2,"Atunci David a zis: „Nimeni nu trebuie să poarte chivotul lui Dumnezeu decât leviții, căci Domnul i-a ales să poarte chivotul lui Dumnezeu și să-i slujească pentru totdeauna.”"],[3,"David a adunat pe tot Israelul la Ierusalim, ca să ducă chivotul Domnului la locul ei, pe care îl pregătise pentru el."],[4,"David a adunat pe fiii lui Aaron și pe leviți:"],[5,"dintre fiii lui Chehat, căpetenia Uriel și frații săi o sută douăzeci;"],[6,"dintre fiii lui Merari, căpetenia Asaia și frații săi două sute douăzeci;"],[7,"dintre fiii lui Gherșom, Ioel căpetenia și frații săi o sută treizeci;"],[8,"din fiii lui Elisafan, căpetenia Şemaia şi două sute de fraţii săi;"],[9,"dintre fiii lui Hebron, căpetenia Eliel și frații lui optzeci;"],[10,"dintre fiii lui Uziel, căpetenia Aminadab și frații săi o sută doisprezece."],[11,"David a chemat pe preoții Țadoc și Abiatar și pe leviți: Uriel, Asaia, Ioel, Șemaia, Eliel și Aminadab,"],[12,"și le-a zis: „Voi sunteți căpeteniile caselor părintești ale leviților. Sfințiți-vă, atât voi, cât și frații voștri, ca să aduceți chivotul Domnului, Dumnezeului lui Israel, în locul pe care i-am pregătit eu."],[13,"Căci, pentru că nu ai purtat-o ​​la început, Domnul Dumnezeul nostru s-a mâniat împotriva noastră, pentru că nu l-am căutat după rânduială.”"],[14,"Astfel, preoții și leviții s-au sfințit ca să ridice chivotul Domnului, Dumnezeului lui Israel."],[15,"Copiii leviților au purtat chivotul lui Dumnezeu pe umeri cu stâlpii ei, așa cum a poruncit Moise, după cuvântul Domnului."],[16,"David a vorbit căpeteniilor leviților să numească pe frații lor cântăreți cu instrumente de muzică, instrumente cu coarde, harpe și chimvale, care sună cu voce tare și își ridică glasul de bucurie."],[17,"Deci leviții l-au numit pe Heman, fiul lui Ioel; și dintre frații săi, Asaf, fiul lui Berechia; și dintre fiii lui Merari, frații lor, Etan, fiul lui Kuşaia;"],[18,"și cu ei frații lor de rangul al doilea: Zaharia, Ben, Iaaziel, Șemiramot, Iehiel, Unni, Eliab, Benaia, Maaseia, Matitia, Elifelehu, Mikneia, Obed-Edom și Ieiel, ușii."],[19,"Astfel cântăreților, Heman, Asaf și Etan, li s-au dat chimvale de aramă, ca să sune cu voce tare;"],[20,"și Zaharia, Aziel, Șemiramot, Iehiel, Unni, Eliab, Maaseia și Benaia, cu instrumente cu coarde puse la Alamot;"],[21,"și Matitia, Elifelehu, Mikneia, Obed-Edom, Ieiel și Azazia, cu harpe acordate la lira cu opt coarde, să conducă."],[22,"Chenania, căpetenia leviților, era peste cântări. I-a învățat pe cântăreți, pentru că era priceput."],[23,"Berechia și Elcana erau paznicii chivotului."],[24,"Sebania, Iosafat, Netanel, Amasai, Zaharia, Benaia și Eliezer, preoții, au sunat din trâmbițe înaintea chivotului lui Dumnezeu; iar Obed-Edom și Iehia erau paznicii chivotului."],[25,"Deci David, bătrânii lui Israel și căpeteniile peste mii au mers să scoată cu bucurie chivotul legământului Domnului din casa lui Obed-Edom."],[26,"Când Dumnezeu i-a ajutat pe leviții care purtau chivotul legământului Domnului, ei au jertfit șapte tauri și șapte berbeci."],[27,"David era îmbrăcat cu o haină de in subțire, la fel ca toți leviții care purtau chivotul, cântăreții și Chenania, maestrul corului, împreună cu cântăreții; și David avea peste el un efod de in."],[28,"Astfel, tot Israelul a adus chivotul legământului Domnului cu strigăte, cu sunet de cornetă, cu trâmbițe și cu chimvale, răsunând cu voce tare cu instrumente cu coarde și harpe."],[29,"Când chivotul legământului Domnului a venit în cetatea lui David, Mical, fiica lui Saul, s-a uitat pe fereastră și l-a văzut pe regele David dansând și cântând; şi l-a dispreţuit în inima ei."]]],[16,[[1,"Au adus chivotul lui Dumnezeu și l-au pus în mijlocul cortului pe care David îl ridicase pentru el; și au adus înaintea lui Dumnezeu arderi de tot și jertfe de mulțumire."],[2,"Când David a terminat de adus arderea de tot și jertfele de mulțumire, a binecuvântat poporul în numele Domnului."],[3,"El a dat fiecăruia din Israel, atât bărbat cât și femeie, fiecăruia o pâine, o porție de carne și o turtă de stafide."],[4,"El a rânduit pe unii dintre leviți să slujească înaintea chivotului Domnului și să pomenească, să mulțumească și să laude pe Domnul, Dumnezeul lui Israel:"],[5,"Asaf, căpetenia, și al doilea după el Zaharia, apoi Ieiel, Șemiramot, Iehiel, Matitia, Eliab, Benaia, Obed-Edom și Ieiel, cu instrumente cu coarde și cu harpe; și Asaf cu chimvale, răsunând cu voce tare;"],[6,"cu Benaia și Iahaziel, preoții cu trâmbițe mereu, înaintea chivotului legământului lui Dumnezeu."],[7,"Atunci, în ziua aceea, David a rânduit întâi să mulțumească Domnului prin mâna lui Asaf și a fraților săi."],[8,"O, mulțumiți lui Iahve."],[9,"Cântați-i."],[10,"Slavă în numele Său sfânt."],[11,"Căutați pe Domnul și puterea Lui."],[12,"Adu-ți aminte de faptele sale minunate pe care le-a făcut,"],[13,"tu, neam al lui Israel, robul lui,"],[14,"El este Domnul Dumnezeul nostru."],[15,"Adu-ți aminte pentru totdeauna de legământul Lui,"],[16,"legământul pe care l-a făcut cu Avraam,"],[17,"El i-a confirmat lui Iacov ca o lege,"],[18,"spunând: „Îți voi da țara Canaanului,"],[19,"când erai doar câțiva bărbați la număr,"],[20,"Au mers din neam în neam,"],[21,"Nu a permis niciunui om să le facă rău."],[22,"„Nu vă atingeți de unșii mei!"],[23,"Cântați Domnului, tot pământul!"],[24,"Vestiți slava Lui între neamuri,"],[25,"Căci mare este Domnul și mult de lăudat."],[26,"Căci toți zeii popoarelor sunt idoli,"],[27,"Onoarea și măreția sunt în fața lui."],[28,"Dați Domnului, familiilor popoarelor,"],[29,"Dați Domnului slava cuvenită Numelui Său."],[30,"Tremură înaintea lui, tot pământul."],[31,"Să se bucure cerurile,"],[32,"Lasă marea să urle și plinătatea ei!"],[33,"Atunci copacii pădurii vor cânta de bucurie înaintea Domnului,"],[34,"Mulțumiți Domnului, căci este bun,"],[35,"Spune: „Mântuiește-ne, Dumnezeul mântuirii noastre!"],[36,"Binecuvântat să fie Domnul, Dumnezeul lui Israel,"],[37,"Așa că a lăsat acolo pe Asaf și pe frații săi, înaintea chivotului legământului Domnului, ca să slujească înaintea chivotului neîncetat, după cum se cere munca zilnică;"],[38,"și Obed-Edom cu rudele lor șaizeci și opt; Obed-Edom, fiul lui Iedutun și Hosa, să fie uși;"],[39,"și preotul Țadoc și preoții fraților săi, înaintea cortului Domnului, în înălțimea care era la Gabaon,"],[40,"să aducă Domnului arderi de tot pe altarul arderilor de tot dimineața și seara, după tot ce este scris în Legea Domnului, pe care a poruncit-o lui Israel;"],[41,"și împreună cu ei Heman și Iedutun și ceilalți care au fost aleși, care au fost pomeniți pe nume, ca să mulțumească Domnului, pentru că bunătatea Lui este în veac;"],[42,"și cu ei Heman și Iedutun cu trâmbițe și chimvale pentru cei care să sune cu voce tare și cu unelte pentru cântările lui Dumnezeu și fiii lui Iedutun să fie la poartă."],[43,"Tot poporul a plecat, fiecare la casa lui; și David s-a întors să-și binecuvânteze casa."]]],[17,[[1,"Când David locuia în casa lui, David i-a spus profetului Natan: „Iată, eu locuiesc într-o casă de cedru, dar chivotul legământului Domnului este într-un cort”."],[2,"Natan i-a zis lui David: „Fă tot ce ai în inima ta, căci Dumnezeu este cu tine”."],[3,"În aceeași noapte, Cuvântul lui Dumnezeu a venit lui Natan, zicând:"],[4,"„Du-te și spune-i lui David robului meu: „Domnul zice: „Nu-mi vei zidi o casă în care să locuiesc;"],[5,"căci nu am locuit într-o casă din ziua în care am adus pe Israel până în ziua de azi, ci am mers din cort în cort și dintr-un cort în altul."],[6,"În toate locurile în care am umblat cu tot Israelul, am spus vreun cuvânt cu vreunul dintre judecătorii lui Israel, căruia i-am poruncit să fie păstorul poporului meu, zicând: „De ce nu mi-ați zidit o casă de cedru?”"],[7,"„Acum, deci, să-i spui robului meu David: „Domnul oștirilor spune: „Te-am luat din țarcul oilor, din urma oilor, ca să fii prinț peste poporul meu Israel."],[8,"Am fost cu tine oriunde ai mers și i-am nimicit pe toți vrăjmașii tăi dinaintea ta. Îți voi face un nume ca numele celor mari care sunt pe pământ."],[9,"Voi pune un loc poporului Meu Israel și-l voi sădi, ca să locuiască în locul lui și să nu se mai miște. Copiii răutății nu-i vor mai risipi, ca la început,"],[10,"și din ziua în care am poruncit judecătorilor să fie peste poporul meu Israel. Îți voi supune pe toți dușmanii tăi. Mai mult, vă spun că Domnul vă va zidi o casă."],[11,"Se va întâmpla, când se vor împlini zilele tale, când trebuie să te duci să fii cu părinţii tăi, să-ţi aşez după tine sămânţa, care va fi dintre fiii tăi; și voi întări împărăția lui."],[12,"El îmi va zidi o casă și îi voi întări tronul pentru totdeauna."],[13,"Eu îi voi fi tată, iar el va fi fiul meu. Nu-mi voi lua bunătatea mea iubitoare de la el, așa cum am luat-o de la cel care a fost înaintea ta;"],[14,"dar îl voi așeza în casa mea și în împărăția mea pentru totdeauna. Tronul Lui va fi întărit pentru totdeauna.”’”"],[15,"După toate aceste cuvinte și după toată această vedenie, așa i-a vorbit Natan lui David."],[16,"Atunci regele David a intrat și a șezut înaintea Domnului; și a zis: „Cine sunt eu, Domnul Dumnezeu, și care este casa mea, că m-ai dus până aici?"],[17,"Acest lucru a fost puțin în ochii tăi, Doamne, dar ai vorbit despre casa robului Tău pentru o perioadă lungă de timp și m-ai respectat după standardul unui om înalt, Domnul Dumnezeu."],[18,"Ce poate să-ți spună David mai mult despre cinstea care i se face slujitorului tău? Căci îl cunoști pe robul tău."],[19,"Doamne, de dragul robului Tău și după inima Ta, ai făcut toată această măreție, ca să faci cunoscute toate aceste lucruri mărețe."],[20,"Doamne, nu este nimeni ca Tine, nici Dumnezeu în afară de Tine, după tot ce am auzit cu urechile noastre."],[21,"Care națiune de pe pământ este ca poporul tău Israel, pe care Dumnezeu s-a dus să-l răscumpere pentru Sine pentru un popor, ca să-ți facă un nume prin lucruri mari și înfricoșătoare, alungând neamuri dinaintea poporului tău pe care l-ai răscumpărat din Egipt?"],[22,"Căci ai făcut pe poporul tău Israel poporul tău pentru totdeauna; iar tu, DOAMNE, ai devenit Dumnezeul lor."],[23,"Acum, Doamne, să fie întărit pentru totdeauna cuvântul pe care l-ai spus despre robul Tău și despre casa lui, și fă cum ai spus."],[24,"Numele tău să fie întărit și mărit pentru totdeauna, zicând: „Domnul oștirilor este Dumnezeul lui Israel, un Dumnezeu al lui Israel. Casa lui David, slujitorul tău, este întărită înaintea ta.”"],[25,"Căci Tu, Dumnezeul meu, i-ai descoperit robului tău că îi vei zidi o casă. De aceea slujitorul tău a găsit curaj să se roage înaintea ta."],[26,"Acum, Doamne, Tu ești Dumnezeu și ai făgăduit acest lucru bun robului Tău."],[27,"Acum ți-a plăcut să binecuvântezi casa robului tău, ca să rămână pentru totdeauna înaintea ta; căci Tu, Doamne, ai binecuvântat și este binecuvântat în veci”."]]],[18,[[1,"După aceea, David a învins pe filisteni și i-a supus și a luat Gat și cetățile lui din mâna filistenilor."],[2,"El a învins Moabul; și moabiții au devenit slujitori lui David și au adus tribut."],[3,"David l-a învins pe Hadadezer, regele Ţoba, spre Hamat, în timp ce se ducea să-şi întărească stăpânirea lângă râul Eufrat."],[4,"David a luat de la el o mie de care, șapte mii de călăreți și douăzeci de mii de pedeși; și David a întins toți caii de la care, dar a păstrat din ei câte pentru o sută de care."],[5,"Când sirienii din Damasc au venit să-l ajute pe Hadadezer, regele Ţoba, David a lovit douăzeci şi două de mii de oameni dintre sirieni."],[6,"Atunci David a pus garnizoane în Siria Damascului; și sirienii au devenit slujitori lui David și au adus tribut. Domnul i-a dat biruință lui David oriunde mergea."],[7,"David a luat scuturile de aur care erau pe slujitorii lui Hadadezer și le-a adus la Ierusalim."],[8,"Din Tibhat și din Cun, cetățile lui Hadadezer, David a luat foarte mult aramă, cu care Solomon a făcut marea de aramă, stâlpii și vasele de aramă."],[9,"Când Tou, împăratul Hamatului, a auzit că David a lovit toată oastea lui Hadadezer, împăratul Țoba,"],[10,"a trimis pe Hadoram, fiul său, la împăratul David, ca să-l întâmpine și să-l binecuvânteze, pentru că luptase împotriva lui Hadadezer și l-a lovit (căci Hadadezer avea războaie cu Tou); și avea cu el tot felul de vase de aur, de argint și de aramă."],[11,"Împăratul David le-a închinat și pe acestea Domnului, cu argintul și aurul pe care le-a luat din toate neamurile: din Edom, din Moab, din fiii lui Amon, din filisteni și din Amalec."],[12,"Mai mult, Abisai, fiul Țeruiei, a lovit optsprezece mii de edomiți în Valea Sării."],[13,"El a pus garnizoane în Edom; și toți edomiții au devenit slujitori ai lui David. Domnul i-a dat biruință lui David oriunde mergea."],[14,"David a domnit peste tot Israelul; și a făcut dreptate și dreptate pentru tot poporul său."],[15,"Ioab, fiul Țeruiei, era peste oști; Iosafat, fiul lui Ahilud, era scriitor;"],[16,"Țadoc, fiul lui Ahitub, și Abimelec, fiul lui Abiatar, erau preoți; Shavsha era scrib;"],[17,"Benaia, fiul lui Iehoiada, era peste cheretiți și peletiți; iar fiii lui David erau căpetenii în slujba regelui."]]],[19,[[1,"După aceasta, Nahaș, împăratul fiilor lui Amon, a murit și fiul său a domnit în locul lui."],[2,"David a spus: „Voi arăta bunătate față de Hanun, fiul lui Nahaș, pentru că tatăl său a fost bună cu mine.”"],[3,"Dar căpeteniile fiilor lui Amon i-au zis lui Hanun: „Crezi că David cinstește pe tatăl tău, pentru că ți-a trimis mângâietori? Nu au venit slujitorii lui la tine să cerceteze, să răstoarne și să iscodească țara?”"],[4,"Așa că Hanun a luat pe slujitorii lui David, i-a bărbierit și le-a tăiat hainele la mijloc la fese și i-a dat afară."],[5,"Atunci unii oameni au mers și i-au spus lui David cum au fost tratați oamenii. El a trimis în întâmpinarea lor; căci bărbaţii au fost foarte umiliţi. Împăratul a zis: „Rămâi la Ierihon până ți-a crescut bărbii și apoi întoarce-te.”"],[6,"Când copiii lui Amon au văzut că s-au făcut odioși lui David, Hanun și fiii lui Amon au trimis o mie de talanți de argint să închirieze care și călăreți din Mesopotamia, din Aram-Maaca și din Țoba."],[7,"Deci au închiriat pentru ei treizeci și două de mii de care și pe regele Maaca cu poporul său, care au venit și au tăbărât lângă Medeba. Copiii lui Amon s-au adunat din cetățile lor și au venit la luptă."],[8,"Când a auzit David de aceasta, a trimis pe Ioab cu toată oastea puternicilor."],[9,"Fiii lui Amon au ieșit și au pus luptă la poarta cetății; iar regii care veniseră erau singuri pe câmp."],[10,"Când Ioab a văzut că bătălia era purtată împotriva lui înainte și în spate, a ales pe câțiva dintre toți bărbații aleși ai lui Israel și i-a pus la rând împotriva sirienilor."],[11,"Pe restul poporului l-a dat în mâna lui Abişai, fratele său; și s-au adunat împotriva copiilor lui Amon."],[12,"El a spus: „Dacă sirienii sunt prea puternici pentru mine, atunci să mă ajuți; dar dacă copiii lui Amon sunt prea puternici pentru tine, atunci te voi ajuta."],[13,"Fiți curajoși și să fim tari pentru poporul nostru și pentru cetățile Dumnezeului nostru. Domnul să facă ceea ce i se pare bine.”"],[14,"Ioab și poporul care era cu el s-a apropiat de luptă înaintea sirienilor; și au fugit înaintea lui."],[15,"Când au văzut copiii lui Amon că sirienii au fugit, și ei au fugit și ei înaintea fratelui său Abisai și au intrat în cetate. Atunci Ioab a venit la Ierusalim."],[16,"Când sirienii au văzut că au fost înfrânți de Israel, au trimis soli și au chemat pe sirienii care erau dincolo de râu, avându-i în frunte pe Șofac, căpetenia armatei lui Hadadezer."],[17,"Lui David i s-a spus că, așa că a adunat pe tot Israelul, a trecut Iordanul, a venit la ei și a pregătit lupta împotriva lor. Deci, după ce David a pregătit lupta împotriva sirienilor, ei au luptat cu el."],[18,"Sirienii au fugit dinaintea lui Israel; și David a ucis dintre bărbații sirieni șapte mii de care și patruzeci de mii de pedeși și a ucis și pe Șofac, căpetenia armatei."],[19,"Când slujitorii lui Hadadezer au văzut că au fost înfrânți de Israel, au făcut pace cu David și i-au slujit. Sirienii nu i-au mai ajutat pe copiii lui Amon."]]],[20,[[1,"La vremea întoarcerii anului, la vremea când împărații ies, Ioab a condus armata și a pustiit țara copiilor lui Amon și a venit și a asediat Raba. Dar David a rămas la Ierusalim. Ioab a lovit Raba și a răsturnat-o."],[2,"David a luat coroana regelui lor de pe capul lui și a găsit că cântărea un talant de aur și erau pietre prețioase în ea. A fost pusă pe capul lui David și el a adus foarte mult pradă din oraș."],[3,"El a scos pe oamenii care erau în ea și ia tăiat cu ferăstrău, cu târâi de fier și cu topoare. David a făcut așa cu toate cetățile fiilor lui Amon. Atunci David și tot poporul s-au întors la Ierusalim."],[4,"După aceasta, la Ghezer a început război cu filistenii. Atunci Sibecai Huşatitul a ucis pe Sippai, dintre fiii uriaşului; si au fost supusi."],[5,"Din nou a fost război cu filistenii; și Elhanan, fiul lui Iair, a ucis pe Lahmi, fratele lui Goliat Gatitul, toiagul a cărui suliță era ca bârna unui țesător."],[6,"A fost din nou război la Gat, unde era un bărbat de statură mare, care avea douăzeci și patru de degete de la mâini și de la picioare, șase la fiecare mână și șase la fiecare picior; și s-a născut și el uriașului."],[7,"Când a sfidat pe Israel, Ionatan, fiul lui Şimeea, fratele lui David, l-a ucis."],[8,"Aceștia s-au născut uriașului din Gat; și au căzut în mâna lui David și în mâna slujitorilor lui."]]],[21,[[1,"Satana s-a ridicat împotriva lui Israel și l-a determinat pe David să facă un recensământ al lui Israel."],[2,"David a zis lui Ioab și căpeteniilor poporului: „Duceți-vă, numărați pe Israel de la Beer-Șeba până la Dan și anunțați-mi, ca să știu câți sunt.”"],[3,"Ioab a zis: \"Domnul să-și facă poporul de o sută de ori mai mare decât ei. Dar, stăpâne, regele, nu sunt ei toți slujitorii domnului meu? De ce cere domnul meu lucrul acesta? De ce va fi el o pricină de vinovăție pentru Israel?\""],[4,"Cu toate acestea, cuvântul regelui a biruit asupra lui Ioab. De aceea Ioab a plecat și a străbătut tot Israelul, apoi a venit la Ierusalim."],[5,"Ioab ia dat lui David suma recensământului poporului. Toți cei din Israel erau un milion o sută de mii de oameni care scoteau o sabie; și în Iuda erau patru sute șaptezeci de mii de oameni care scoteau sabia."],[6,"Dar el nu i-a numărat pe Levi și pe Beniamin printre ei, pentru că cuvântul regelui era urâtor pentru Ioab."],[7,"Dumnezeu a fost nemulțumit de acest lucru; de aceea a lovit pe Israel."],[8,"David a zis lui Dumnezeu: „Am păcătuit foarte mult, făcând acest lucru; dar acum, te rog, îndepărtează nelegiuirea robului tău, căci am făcut o foarte nebunie.”"],[9,"Domnul a vorbit lui Gad, văzătorul lui David, zicând:"],[10,"„Du-te și vorbește cu David și spune-i: „Domnul spune: „Îți ofer trei lucruri. Alege unul dintre ei, ca să ți-o fac eu.”’”"],[11,"Atunci Gad a venit la David și i-a zis: „Domnul spune: „Alege-ți!"],[12,"fie trei ani de foamete; sau trei luni să fie mistuit înaintea vrăjmașilor tăi, în timp ce sabia vrăjmașilor tăi te va atinge; sau trei zile de sabia Domnului, ciuma în țară și îngerul Domnului nimicind prin toate hotarele lui Israel. Acum, deci, gândiți-vă ce răspuns voi întoarce celui ce m-a trimis.”"],[13,"David a zis lui Gad: \"Sunt în necaz; mă rog, să cad în mâna Domnului, căci îndurările Lui sunt foarte mari. Nu mă lăsa să cad în mâna omului.\""],[14,"Deci Domnul a trimis ciuma asupra lui Israel și au căzut șaptezeci de mii de oameni din Israel."],[15,"Dumnezeu a trimis un înger la Ierusalim să-l distrugă. Pe când era pe punctul de a nimici, Domnul a văzut și s-a călit de nenorocire și a zis îngerului nimicitor: „Este de ajuns, acum retrage-ți mâna.” Îngerul Domnului stătea lângă aria lui Ornan, iebusitul."],[16,"David și-a ridicat ochii și a văzut pe îngerul Domnului stând între pământ și cer, având în mână o sabie scoasă întinsă peste Ierusalim."],[17,"David a zis lui Dumnezeu: \"Nu eu am poruncit ca poporul să fie numărat? Eu sunt cel care am păcătuit și am făcut foarte rău; dar aceste oi, ce au făcut ei? Te rog, lasă mâna Ta, Doamne, Dumnezeul meu, să fie împotriva mea și împotriva casei tatălui meu, dar nu împotriva poporului Tău, ca să fie lovite.\""],[18,"Atunci îngerul Domnului i-a poruncit lui Gad să-i spună lui David că David să se suie și să ridice un altar Domnului în aria lui Ornan, iebusitul."],[19,"David s-a suit la cuvântul lui Gad, pe care le-a spus în numele Domnului."],[20,"Ornan s-a întors și l-a văzut pe înger; şi cei patru fii ai săi care erau cu el s-au ascuns. Acum Ornan treiera grâul."],[21,"Când David a venit la Ornan, Ornan s-a uitat și l-a văzut pe David și a ieșit din aria, și s-a închinat înaintea lui David cu fața la pământ."],[22,"Atunci David i-a zis lui Ornan: „Vinde-mi locul acestei aria, ca să zid pe ea un altar Domnului; să-mi vinzi cu prețul întreg, ca să se oprească urgia de la chinuirea poporului.”"],[23,"Ornan i-a zis lui David: \"Ia-l pentru tine și stăpânul meu regele să facă ce este bine în ochii lui. Iată, dau boii pentru arderile de tot și uneltele de treierat pentru lemne și grâul pentru dar de mâncare. Eu dau totul.\""],[24,"Împăratul David i-a spus lui Ornan: „Nu, dar cu siguranță îl voi cumpăra la prețul întreg, căci nu voi lua Domnului ceea ce este al tău și nici nu voi aduce arderi de tot care să nu mă coste nimic.”"],[25,"Deci David ia dat lui Ornan șase sute de sicli de aur, în greutate, pentru locul respectiv."],[26,"David a zidit acolo un altar Domnului, a adus arderi de tot și jertfe de mulțumire și a chemat pe Domnul; și i-a răspuns din cer prin foc pe altarul arderilor de tot."],[27,"Atunci DOMNUL a poruncit îngerului și a pus sabia înapoi în teacă."],[28,"În vremea aceea, când a văzut David că Domnul i-a răspuns în aria lui Ornan, iebusitul, a adus jertfe acolo."],[29,"Căci cortul Domnului, pe care l-a făcut Moise în pustiu, și altarul arderilor de tot, erau în vremea aceea în înălțimea Gabaonului."],[30,"Dar David nu a putut să meargă înaintea ei să-l întrebe pe Dumnezeu, pentru că i-a fost frică din cauza sabiei îngerului Domnului."]]],[22,[[1,"Atunci David a zis: „Aceasta este casa Domnului Dumnezeu și acesta este altarul arderilor de tot pentru Israel”."],[2,"David a poruncit să adune străinii care erau în țara lui Israel; și a pus zidari să taie pietre împletite pentru a construi casa lui Dumnezeu."],[3,"David a pregătit fier din belșug pentru cuiele ușilor porților și pentru cuplaje și bronz din belșug fără greutate,"],[4,"și cedri nenumărați, căci sidonienii și poporul Tir au adus cedri din belșug lui David."],[5,"David a spus: „Fiul meu Solomon este tânăr și tandru, și casa care va fi zidită Domnului trebuie să fie nemaipomenit de măreț, de faimă și de glorie în toate țările. De aceea o voi pregăti.” Așa că David s-a pregătit din belșug înainte de moartea lui."],[6,"Apoi a chemat pe Solomon, fiul său, și i-a poruncit să zidească o casă pentru Domnul, Dumnezeul lui Israel."],[7,"David a zis lui Solomon, fiul său: „În ceea ce mă priveşte, am avut în inima mea să zid o casă Numelui Domnului Dumnezeului meu."],[8,"Dar cuvântul Domnului mi-a venit, zicând: „Ai vărsat din belșug sânge și ai făcut războaie mari. Nu vei zidi o casă Numelui Meu, pentru că ai vărsat mult sânge pe pământ în ochii Mei."],[9,"Iată, ți se va naște un fiu, care va fi un om al păcii. Îi voi odihni de toți vrăjmașii lui din jur; căci numele lui va fi Solomon și voi da lui Israel pace și liniște în zilele lui."],[10,"El va zidi o casă numelui Meu; şi el va fi fiul meu, iar eu îi voi fi tată; și voi întări tronul împărăției lui peste Israel pentru totdeauna.”"],[11,"Acum, fiul meu, Domnul să fie cu tine și să te prospere și să zidească Casa Domnului Dumnezeului tău, așa cum a vorbit despre tine."],[12,"Domnul să vă dea pricepere și pricepere și să vă pună în fruntea lui Israel, ca să păziți Legea Domnului Dumnezeului vostru."],[13,"Atunci veți prospera, dacă veți păzi să împliniți legile și poruncile pe care Domnul le-a dat lui Moise cu privire la Israel. Fii puternic și curajos. Nu-ți fie frică și nu fi consternat."],[14,"Acum, iată, în necazul meu, am pregătit pentru Casa Domnului o sută de mii de talanți de aur, un milion de talanți de argint și aramă și fier fără greutate; căci este din belșug. Am pregătit și cherestea și piatră; și puteți adăuga la ele."],[15,"De asemenea, sunt cu voi muncitori din belșug: tăietori și lucrători de piatră și cherestea, și tot felul de oameni pricepuți în orice fel de lucrare;"],[16,"dintre aur, argint, bronz și fier, nu există număr. Scoală-te și fă, și Domnul să fie cu tine.”"],[17,"De asemenea, David a poruncit tuturor căpeteniilor lui Israel să ajute fiul său Solomon, zicând:"],[18,"„Nu este Domnul Dumnezeul tău cu tine? Nu ți-a dat El odihnă din toate părțile? Căci i-a dat pe locuitorii țării în mâna mea și țara este supusă înaintea Domnului și înaintea poporului Său."],[19,"Acum pune-ți inima și sufletul să urmeze pe Domnul Dumnezeul tău. Scoală-te deci și zidește sanctuarul Domnului Dumnezeu, ca să aduci chivotul legământului Domnului și vasele sfinte ale lui Dumnezeu în casa care va fi zidită Numelui Domnului.”"]]],[23,[[1,"David era bătrân și plin de zile; și a pus pe fiul său pe Solomon împărat peste Israel."],[2,"El a adunat pe toți căpeteniile lui Israel, cu preoții și cu leviții."],[3,"Leviții au fost numărați de la vârsta de treizeci de ani în sus; și numărul lor, după scrutinele lor, om după om, a fost de treizeci și opt de mii."],[4,"David a spus: „Din aceștia douăzeci și patru de mii trebuiau să supravegheze lucrarea Casei Domnului, șase mii erau ofițeri și judecători,"],[5,"patru mii erau ușiri și patru mii au lăudat pe Domnul cu uneltele pe care le-am făcut pentru a lăuda.”"],[6,"David i-a împărțit în divizii, după fiii lui Levi: Gherșon, Chehat și Merari."],[7,"Dintre Gherșoniți: Ladan și Șimei."],[8,"Fiii lui Ladan: Iehiel, căpetenia, Zetam și Ioel, trei."],[9,"Fiii lui Șimei: Șelomot, Haziel și Haran, trei. Aceștia erau șefii caselor părinților lui Ladan."],[10,"Fiii lui Şimei: Iahat, Zina, Ieuş şi Beria. Acești patru au fost fiii lui Șimei."],[11,"Iahat era căpetenia, iar Ziza al doilea; dar Ieuș și Beria nu au avut mulți fii; de aceea au devenit o casă a părinților într-o singură socoteală."],[12,"Fiii lui Chehat: Amram, Ițehar, Hebron și Uziel, patru."],[13,"Fiii lui Amram: Aaron și Moise; și Aaron a fost despărțit ca să sfințească lucrurile preasfinte, el și fiii lui pentru totdeauna, ca să ardă tămâie înaintea Domnului, să-i slujească și să binecuvânteze în numele Lui pentru totdeauna."],[14,"Dar în ceea ce privește Moise, omul lui Dumnezeu, fiii lui au fost numiți printre seminția lui Levi."],[15,"Fiii lui Moise: Gherșom și Eliezer."],[16,"Fiii lui Gherșom: Șebuel, căpetenia."],[17,"Fiul lui Eliezer era căpetenia Rehabia; și Eliezer nu a avut alți fii, dar fiii lui Rehabia au fost foarte mulți."],[18,"Fiul lui Ițehar: șeful șelomit."],[19,"Fiii lui Hebron: Ieria, căpetenia, Amaria, al doilea, Iahaziel, al treilea, și Iekameam, al patrulea."],[20,"Fiii lui Uziel: Mica, căpetenia, și Ișia, al doilea."],[21,"Fiii lui Merari: Mahli și Muși. Fiii lui Mahli: Eleazar și Chiș."],[22,"Eleazar a murit și nu a avut fii, ci numai fiice; și rudele lor, fiii lui Chiș, i-au luat de soții."],[23,"Fiii lui Muși: Mahli, Eder și Ieremot, trei."],[24,"Aceștia au fost fiii lui Levi, după casele lor părintești, chiar și capii caselor părintești ale celor care au fost numărați în parte, după numărul numelor, după scrutinele lor, care făceau lucrarea pentru slujba Casei Domnului, de la vârsta de douăzeci de ani în sus."],[25,"Căci David a spus: „Domnul, Dumnezeul lui Israel, a dat odihnă poporului său și locuiește în Ierusalim pentru totdeauna."],[26,"De asemenea, leviții nu vor mai avea nevoie să ducă cortul și toate vasele lui pentru slujba lui.”"],[27,"Căci după ultimele cuvinte ale lui David au fost numărați fiii lui Levi, de la vârsta de douăzeci de ani în sus."],[28,"Căci datoria lor era să-i aştepte pe fiii lui Aaron pentru slujirea Casei Domnului – în curţi, în camere şi în curăţirea tuturor lucrurilor sfinte, chiar în lucrarea slujirii Casei lui Dumnezeu;"],[29,"de asemenea, pentru pâinea de prezentare și pentru făina fină pentru dar de mâncare, fie din napolitană nedospită, fie din cea care se coace în tigaie, fie din cea care este înmuiată, și pentru toate măsurătorile de cantitate și dimensiune;"],[30,"și să stea în fiecare dimineață să mulțumească și să laude pe Domnul, și la fel și seara;"],[31,"și să aducă Domnului toate arderile de tot în zilele de Sabat, în lunile noi și la sărbătorile stabilite, în număr, conform rânduinței cu privire la ele, în permanență înaintea Domnului;"],[32,"și să păzească datoria Cortului Întâlnirii, datoria locașului sfânt și datoria fiilor lui Aaron, frații lor, pentru slujirea Casei Domnului."]]],[24,[[1,"Acestea au fost diviziile fiilor lui Aaron. Fiii lui Aaron: Nadab, Abihu, Eleazar și Itamar."],[2,"Dar Nadab și Abihu au murit înaintea tatălui lor și nu au avut copii; de aceea Eleazar și Itamar au slujit ca preoți."],[3,"David, împreună cu Țadoc din fiii lui Eleazar și Ahimelec dintre fiii lui Itamar, i-a împărțit după rânduiala lor în serviciul lor."],[4,"S-au găsit mai mulți bărbați de căpetenie dintre fiii lui Eleazar decât dintre fiii lui Itamar; și au fost împărțiți astfel: dintre fiii lui Eleazar au fost șaisprezece, căpetenii de case; iar din fiii lui Itamar, după casele părinților lor, opt."],[5,"Astfel, ei au fost împărțiți în mod imparțial prin tragere la sorți; căci erau căpetenii sanctuarului și căpetenii lui Dumnezeu, atât dintre fiii lui Eleazar, cât și dintre fiii lui Itamar."],[6,"Șemaia, fiul lui Netanel, cărturarul, care era dintre leviți, le-a scris în prezența regelui, a căpeteniilor, a preotului Țadoc, a lui Ahimelec, fiul lui Abiatar, și a căpeteniilor caselor părintești ale preoților și ale leviților; o casă părintească a fost luată pentru Eleazar și alta pentru Itamar."],[7,"Primul lot i-a ieșit lui Ioiarib, al doilea lui Iedaia,"],[8,"al treilea lui Harim, al patrulea lui Seorim,"],[9,"al cincilea lui Malchia, al șaselea lui Miiamin,"],[10,"al șaptelea lui Hacoț, al optulea lui Abia,"],[11,"al nouălea lui Iosua, al zecelea lui Şecania,"],[12,"al unsprezecelea lui Eliașib, al doisprezecelea lui Iakim,"],[13,"al treisprezecelea lui Hupa, al patrusprezecelea lui Ieşebeab,"],[14,"al cincisprezecelea pentru Bilga, al șaisprezecelea pentru Imer,"],[15,"al șaptesprezecelea lui Hezir, al optsprezecelea lui Happizzez,"],[16,"al nouăsprezecelea lui Pethahia, al douăzecilea lui Ihezkel,"],[17,"al douăzeci și unu lui Iachin, al douăzeci și al doilea lui Gamul,"],[18,"al douăzeci şi treilea lui Delaia, şi al douăzeci şi patrulea lui Maazia."],[19,"Acesta a fost porunca lor în slujba lor, să intre în casa Domnului, după rânduiala dată lor de Aaron, tatăl lor, așa cum îi poruncise Domnul, Dumnezeul lui Israel."],[20,"Din ceilalţi fii ai lui Levi: dintre fiii lui Amram, Şubael; din fiii lui Şubael, Iehdeia."],[21,"Din Rehabia: dintre fiii lui Rehabia, Ișia, căpetenia."],[22,"Dintre Ițehariți, Șelomot; din fiii lui Şelomot, Iahat."],[23,"Fiii lui Hebron: Ieria, Amaria al doilea, Iahaziel al treilea și Iekameam al patrulea."],[24,"Fiii lui Uziel: Mica; dintre fiii lui Mica, Şamir."],[25,"Fratele lui Mica: Issia; din fiii lui Issia, Zaharia."],[26,"Fiii lui Merari: Mahli și Muși. Fiul lui Iaazia: Beno."],[27,"Fiii lui Merari de la Iaazia: Beno, Șoham, Zacur și Ibri."],[28,"Din Mahli: Eleazar, care nu a avut fii."],[29,"Din Chiș, fiul lui Chiș: Ierahmeel."],[30,"Fiii lui Muși: Mahli, Eder și Ierimot. Aceștia au fost fiii leviților după casele părinților lor."],[31,"Aceștia au tras la sorți, la fel ca și frații lor, fiii lui Aaron, în fața împăratului David, Țadoc, Ahimelec și a căpeteniilor caselor părintești ale preoților și ale leviților, casele părintești ale căpeteniei, ca și ale fratelui său mai mic."]]],[25,[[1,"Mai mult, David și căpeteniile armatei i-au pus deoparte pentru slujire pe câțiva dintre fiii lui Asaf, ai lui Heman și ai lui Iedutun, care trebuiau să prorocească cu harpe, cu instrumente cu coarde și cu chimvale. Numărul celor care au făcut lucrarea conform serviciului lor a fost:"],[2,"dintre fiii lui Asaf: Zacur, Iosif, Netania și Așarela. Fiii lui Asaf erau sub mâna lui Asaf, care proorocea la ordinul regelui."],[3,"Din Iedutun, fiii lui Iedutun: Ghedalia, Ţeri, Iesaia, Şimei, Haşabia şi Matitia, şase, sub mâna tatălui lor Iedutun, care a proorocit mulţumind şi lăudând pe Domnul cu harpa."],[4,"Dintre Heman, fiii lui Heman: Buchia, Matania, Uziel, Şebuel, Ierimot, Hanania, Hanani, Iliata, Ghiddalti, Romamti-Ezer, Iosbecaşa, Malloti, Hotir şi Mahaziot."],[5,"Toți aceștia au fost fiii lui Heman, văzătorul regelui, în cuvintele lui Dumnezeu, ca să ridice cornul. Dumnezeu i-a dat lui Heman paisprezece fii și trei fiice."],[6,"Toți aceștia erau sub mâna tatălui lor pentru cântare în Casa Domnului, cu chimvale, instrumente cu coarde și harpe, pentru slujba Casei lui Dumnezeu: Asaf, Iedutun și Heman, fiind sub porunca împăratului."],[7,"Numărul lor, împreună cu frații lor, care erau instruiți să cânte Domnului, toți cei pricepuți, a fost două sute optzeci și opt."],[8,"Ei au tras la sorți pentru birourile lor, toți deopotrivă, cei mici și cei mari, atât profesorul cât și elevul."],[9,"Primul lot a ieşit pentru Asaf lui Iosif; al doilea, după Ghedalia, el și frații și fiii săi erau doisprezece;"],[10,"al treilea lui Zacur, fiii și frații săi, doisprezece;"],[11,"al patrulea lui Izri, fiii și frații săi, doisprezece;"],[12,"al cincilea lui Netania, fiii și frații săi, doisprezece;"],[13,"al șaselea lui Buchia, fiii și frații săi, doisprezece;"],[14,"al şaptelea lui Işarela, fiii şi fraţii săi, doisprezece;"],[15,"al optulea lui Iesaia, fiii și frații săi, doisprezece;"],[16,"al nouălea lui Matania, fiii și frații săi, doisprezece;"],[17,"al zecelea lui Şimei, fiii şi fraţii săi, doisprezece;"],[18,"al unsprezecelea lui Azarel, fiii și frații săi, doisprezece;"],[19,"al doisprezecelea lui Haşabia, fiii şi fraţii săi, doisprezece;"],[20,"pentru al treisprezecelea, Şubael, fiii şi fraţii săi, doisprezece;"],[21,"pentru al patrusprezecelea, Matitia, fiii și frații săi, doisprezece;"],[22,"pentru al cincisprezecelea pentru Ieremot, fiii și frații săi, doisprezece;"],[23,"pentru al șaisprezecelea lui Hanania, fiii și frații săi, doisprezece;"],[24,"pentru al șaptesprezecelea, pentru Iosbecașa, fiii și frații săi, doisprezece;"],[25,"pentru al optsprezecelea lui Hanani, fiii și frații săi, doisprezece;"],[26,"pentru al nouăsprezecelea lui Mallothi, fiii și frații săi, doisprezece;"],[27,"pentru al douăzecilea lui Iliata, fiii și frații săi, doisprezece;"],[28,"pentru al douăzeci și unu pentru Hothir, fiii și frații săi, doisprezece;"],[29,"pentru al douăzeci și doi la Giddalti, fiii și frații săi, doisprezece;"],[30,"pentru al douăzeci și treilea lui Mahaziot, fiii și frații săi, doisprezece;"],[31,"pentru al douăzeci și patrulea lui Romamti-Ezer, fiii și frații săi, doisprezece."]]],[26,[[1,"Pentru diviziile ușilor: dintre Corehiți, Meșelemia, fiul lui Core, dintre fiii lui Asaf."],[2,"Meşelemia a avut fii: Zaharia, întâiul născut, Iediael al doilea, Zebadia al treilea, Jatniel al patrulea,"],[3,"Elam al cincilea, Iohanan al șaselea și Eliehoenai al șaptelea."],[4,"Obed-Edom a avut fii: Semaia primul născut, Iozabad al doilea, Ioah al treilea, Sacar al patrulea, Netanel al cincilea,"],[5,"Amiel al șaselea, Isahar al șaptelea și Peuletai al optulea; căci Dumnezeu l-a binecuvântat."],[6,"Fii i s-au născut și lui Șemaia, fiul său, care a domnit peste casa tatălui lor; căci erau oameni viteji şi viteji."],[7,"Fiii lui Semaia: Otni, Refael, Obed și Elzabad, ale căror rude erau bărbați viteji, Elihu și Semachia."],[8,"Toți aceștia erau din fiii lui Obed-Edom, cu fiii și frații lor, oameni pricepuți, în putere pentru slujire: șaizeci și doi din Obed-Edom."],[9,"Meşelemia a avut fii şi fraţi, optsprezece bărbaţi viteji."],[10,"De asemenea, Hosa, din fiii lui Merari, a avut fii: Șimri, căpetenia (căci deși nu era întâiul născut, totuși tatăl său l-a pus căpetenie),"],[11,"Hilchia al doilea, Tebalia al treilea și Zaharia al patrulea. Toți fiii și frații lui Hosa au fost treisprezece."],[12,"Dintre aceștia au fost diviziile ușarilor, chiar și a bărbaților de frunte, care aveau slujbe ca frații lor, pentru a sluji în Casa Domnului."],[13,"Ei au tras la sorți, atât cei mici cât și cei mari, după casele părinților lor, pentru fiecare poartă."],[14,"Sortul spre răsărit a căzut lui Şelemia. Apoi, pentru fiul său Zaharia, un sfetnic înțelept, au tras la sorți; iar soarta lui a ieşit spre nord."],[15,"spre Obed-Edom spre sud; iar fiilor săi magazia."],[16,"Spre Șupim și Hosa, spre vest, lângă poarta Șalechet, pe drumul care urcă, paznic vizavi de paznic."],[17,"La răsărit erau șase leviți, la miazănoapte patru pe zi, la miazăzi patru pe zi și pentru depozit doi și doi."],[18,"Pentru Parbar spre vest, patru la drum și două la Parbar."],[19,"Acestea erau diviziile ușilor; din fiii Corehiților și din fiii lui Merari."],[20,"Dintre leviți, Ahija era peste comorile casei lui Dumnezeu și peste comorile lucrurilor dedicate."],[21,"Fiii lui Ladan, fiii Gherșoniților, ai lui Ladan, căpeteniile casei părintești ale lui Ladan Gherșonitul: Iehieli."],[22,"Fiii lui Iehieli: Zetam și Ioel, fratele său, peste comorile Casei Domnului."],[23,"Din amramiți, dintre ițehariți, dintre hebroniți, dintre uzieliți:"],[24,"Şebuel, fiul lui Gherşom, fiul lui Moise, era conducător peste vistieriile."],[25,"Frații săi: din Eliezer, fiul său Rehabia și fiul său Iesaia, fiul său Ioram, fiul său Zicri și fiul său Șelomot."],[26,"Acest Șelomot și frații săi erau peste toate vistieriile lucrurilor dedicate, pe care le închinasese regele David și șefii casei părinților, căpeteniile de mii și sute și căpeteniile oștirii."],[27,"Ei au dedicat o parte din prada câștigată în lupte pentru a repara casa Domnului."],[28,"Tot ce au închinat văzătorul Samuel, Saul, fiul lui Chiș, Abner, fiul lui Ner, și Ioab, fiul Țeruiei, oricui închinase ceva, era sub mâna lui Șelomot și a fraților săi."],[29,"Dintre Ițehariți, Chenania și fiii săi au fost numiți la afacerile exterioare peste Israel, ca ofițeri și judecători."],[30,"Din hebroniți, Hașabia și frații săi, o mie șapte sute de bărbați viteji, aveau supravegherea lui Israel dincolo de Iordan, spre vest, pentru toate treburile Domnului și pentru slujirea regelui."],[31,"Dintre hebroniți, Ierija era căpetenia hebroniților, după generațiile lor, după familiile taților. Ei au fost căutați în al patruzecilea an al domniei lui David și au fost găsiți printre ei oameni puternici și viteji la Iazer din Galaad."],[32,"Rudele lui, bărbați viteji, erau două mii șapte sute, șefi de case ale taților, pe care regele David i-a pus supraveghetori peste Rubeniți, Gadiți și jumătate din seminția Manasiților, pentru toate lucrurile legate de Dumnezeu și pentru treburile împăratului."]]],[27,[[1,"Copiii lui Israel, după numărul lor, șefii caselor părintești și căpeteniile de mii și de sute și ofițerii lor care slujeau împăratului în orice chestiune a diviziilor care intrau și ieșeau lună de lună în toate lunile anului; din fiecare divizie erau douăzeci și patru de mii."],[2,"Peste prima divizie pentru prima lună era Iașobeam, fiul lui Zabdiel. În divizia lui erau douăzeci și patru de mii."],[3,"El era dintre copiii lui Pereţ, căpetenia tuturor căpeteniilor oştirii în prima lună."],[4,"Peste divizia celei de-a doua luni era Dodai, Ahohitul, și cetatea lui, și Miclot, conducătorul; și în divizia lui erau douăzeci și patru de mii."],[5,"Al treilea căpetenie al oștirii pentru luna a treia a fost Benaia, fiul preotului principal Iehoiada. În divizia lui erau douăzeci și patru de mii."],[6,"Acesta este Benaia, care a fost puternicul celor treizeci și peste cei treizeci. Din divizia lui era fiul său Ammizabad."],[7,"Al patrulea căpetenie pentru luna a patra a fost Asael, fratele lui Ioab, și Zebadia, fiul său, după el. În divizia lui erau douăzeci și patru de mii."],[8,"Al cincilea căpetenie pentru luna a cincea a fost Şamhut, Izrahitul. În divizia lui erau douăzeci și patru de mii."],[9,"Al șaselea căpitan pentru luna a șasea a fost Ira, fiul lui Ikeș, tecoitul. În divizia lui erau douăzeci și patru de mii."],[10,"Al șaptelea căpetenie pentru luna a șaptea a fost Helez, Pelonitul, din fiii lui Efraim. În divizia lui erau douăzeci și patru de mii."],[11,"Al optulea căpetenie pentru luna a opta a fost Sibecai Huşatitul, din Zerahiţi. În divizia lui erau douăzeci și patru de mii."],[12,"Al nouălea căpetenie pentru luna a noua a fost Abiezer, Anatotul, din Beniamiți. În divizia lui erau douăzeci și patru de mii."],[13,"Al zecelea căpetenie pentru luna a zecea a fost Maharai, netofatitul, din Zerahiți. În divizia lui erau douăzeci și patru de mii."],[14,"Al unsprezecelea căpetenie pentru luna a unsprezecea a fost Benaia, piratonitul, din fiii lui Efraim. În divizia lui erau douăzeci și patru de mii."],[15,"Al doisprezecelea căpetenie pentru luna a douăsprezecea a fost Heldai, netofatitul, din Otniel. În divizia lui erau douăzeci și patru de mii."],[16,"În plus, peste triburile lui Israel: dintre Rubeniți, Eliezer, fiul lui Zicri, era conducător; dintre simeoniți, Șefatia, fiul lui Maaca;"],[17,"din Levi, Haşabia, fiul lui Chemuel; lui Aaron, Ţadoc;"],[18,"din Iuda, Elihu, unul dintre frații lui David; din Isahar, Omri, fiul lui Mihail;"],[19,"din Zabulon, Ismaia, fiul lui Obadia; din Neftali, Ieremot, fiul lui Azriel;"],[20,"din fiii lui Efraim, Osea, fiul lui Azazia; din jumătatea seminției lui Manase, Ioel, fiul lui Pedaia;"],[21,"din jumătatea seminției lui Manase din Galaad, Iddo, fiul lui Zaharia; din Beniamin, Iaasiel, fiul lui Abner;"],[22,"din Dan, Azarel, fiul lui Ieroham. Aceștia erau căpeteniile triburilor lui Israel."],[23,"Dar David nu a luat numărul lor de la vârsta de douăzeci de ani și mai jos, pentru că Domnul spusese că va mări pe Israel ca stelele cerului."],[24,"Ioab, fiul Țeruiei, a început să facă un recensământ, dar nu a terminat; și mânia a venit asupra lui Israel pentru aceasta. Numărul nu a fost trecut în cont în cronicile regelui David."],[25,"Peste comorile regelui era Azmavet, fiul lui Adiel. Peste comorile din câmpuri, din cetăți, din sate și din turnuri era Ionatan, fiul lui Ozia;"],[26,"Peste cei care făceau lucrarea câmpului pentru lucrarea pământului era Ezri, fiul lui Chelub."],[27,"Peste viile era Şimei Ramatitul. Peste creșterea viilor pentru pivnițe a fost Zabdi, Shifmit."],[28,"Peste măslini și sicomori care erau în câmpie era Baal Hanan Ghederitul. Peste pivnițele cu ulei era Ioas."],[29,"Peste turmele care se hrăneau în Sharon era Shitrai Sharonitul. Peste cirezile care erau în văi era Şafat, fiul lui Adlai."],[30,"Peste cămile era Obil Ismaelitul. Peste măgari era Iehdeia Meronotitul. Peste turme era Iaziz Hagritul."],[31,"Toți aceștia erau conducătorii proprietății care era a regelui David."],[32,"De asemenea, Ionatan, unchiul lui David, a fost sfetnic, om priceput și scrib. Iehiel, fiul lui Hacmoni, era cu fiii regelui."],[33,"Ahitofel era consilierul regelui. Huşai Arhitul era prietenul regelui."],[34,"După Ahitofel au fost Iehoiada, fiul lui Benaia, și Abiatar. Ioab era căpitanul armatei regelui."]]],[28,[[1,"David i-a adunat la Ierusalim pe toți căpeteniile lui Israel, căpeteniile triburilor, căpeteniile cetelor care slujeau împăratului prin divizii, căpeteniile de mii, căpeteniile de sute și căpeteniile peste toate averile și averile regelui și ale fiilor săi, împreună cu căpeteniile și oamenii puternici, chiar și toți vitejii."],[2,"Atunci împăratul David s-a ridicat în picioare și a zis: „Ascultați-mă, frații mei și poporul meu! În ceea ce mă privește, aveam în inima mea să zidesc o casă de odihnă pentru chivotul legământului Domnului și pentru așternutul picioarelor Dumnezeului nostru; și am pregătit pentru clădire."],[3,"Dar Dumnezeu mi-a zis: „Să nu construiești o casă numelui Meu, pentru că ești un om de război și ai vărsat sânge”."],[4,"Totuși, Domnul, Dumnezeul lui Israel, m-a ales din toată casa tatălui meu, ca să fiu rege peste Israel pentru totdeauna. Căci el l-a ales pe Iuda ca domn; și în casa lui Iuda, casa tatălui meu; și printre fiii tatălui meu a avut plăcere în mine să mă facă rege peste tot Israelul."],[5,"Dintre toți fiii mei (căci Domnul mi-a dat mulți fii), el l-a ales pe fiul meu Solomon să stea pe tronul împărăției Domnului peste Israel."],[6,"El mi-a zis: „Solomon, fiul tău, îmi va zidi casa și curțile mele; căci l-am ales să fie fiul meu și îi voi fi tată."],[7,"Îi voi întări împărăția pentru totdeauna, dacă va continua să împlinească poruncile și poruncile Mele, așa cum este astăzi.”"],[8,"Acum, deci, înaintea întregului Israel, adunarea Domnului, și în ascultarea Dumnezeului nostru, păziți și căutați toate poruncile Domnului Dumnezeului vostru, ca să stăpâniți această țară bună și să o lăsați moștenire copiilor voștri după voi pentru totdeauna."],[9,"Tu, Solomon, fiul meu, cunoști pe Dumnezeul tatălui tău și slujește-i cu o inimă desăvârșită și cu o minte bună; căci Domnul cercetează toate inimile și înțelege toate închipuirile gândurilor. Dacă îl cauți, el va fi găsit de tine; dar dacă îl părăsești, te va lepăda pentru totdeauna."],[10,"Luați seama acum, căci Domnul v-a ales să zidiți o casă pentru sanctuar. Fii puternic și fă-o.”"],[11,"Atunci David i-a dat fiului său Solomon planurile pridvorului templului, pentru casele lui, pentru vistieriile lui, pentru odăile lui de sus, pentru odăile lui interioare, pentru locul capacului ispășirii;"],[12,"și planurile a tot ce avea prin Duhul, pentru curțile Casei Domnului, pentru toate odăile din jur, pentru vistieriile Casei lui Dumnezeu și pentru vistieriile lucrurilor dedicate;"],[13,"de asemenea, pentru cetățile preoților și ale leviților, pentru toată lucrarea slujbei Casei Domnului și pentru toate uneltele de slujbă din Casa Domnului:"],[14,"de aur în greutate pentru aur pentru toate vasele de orice fel de serviciu, pentru toate vasele de argint în greutate, pentru toate vasele de orice fel de serviciu;"],[15,"de asemenea, în greutate, pentru sfeșnice de aur și pentru lămpile lui, de aur, în greutate pentru fiecare sfeșnic și pentru lămpile lui; și pentru sfeșnice de argint, în greutate pentru fiecare sfeșnic și pentru lămpile lui, după folosirea fiecărui sfeșnic;"],[16,"și aurul în greutate pentru mesele pâinii de prezentare, pentru fiecare masă; și argint pentru mesele de argint;"],[17,"și furculițele, ligheanele și paharele, din aur curat; și pentru bolurile de aur în greutate pentru fiecare vas; și pentru bolurile de argint, în greutate, pentru fiecare vas;"],[18,"iar pentru altarul tămâierii, aur curat în greutate; și aur pentru planurile carului și heruvimii care se întind și acoperă chivotul legământului Domnului."],[19,"„Toate acestea”, a spus David, „am fost făcut să înțeleg în scris din mâna Domnului, chiar și toate lucrările acestui model.”"],[20,"David a zis lui Solomon, fiul său: „Fii tare și curajos și fă asta. Nu te teme și nici nu te înspăimânta, căci Domnul Dumnezeu, Dumnezeul meu, este cu tine; nu te va lăsa și nu te va părăsi, până când se va termina toată lucrarea pentru slujba Casei Domnului."],[21,"Iată, acolo sunt cetăți ale preoților și ale leviților pentru toată slujba casei lui Dumnezeu. Orice om dornic care are pricepere pentru orice fel de serviciu va fi cu tine în orice fel de muncă. De asemenea, căpeteniile și tot poporul vor fi în întregime sub porunca ta.”"]]],[29,[[1,"Împăratul David a zis întregii adunări: „Fiul meu Solomon, pe care singurul l-a ales Dumnezeu, este încă tânăr și tandru și lucrarea este mare, căci palatul nu este pentru om, ci pentru Domnul Dumnezeu."],[2,"Acum am pregătit cu toată puterea pentru casa Dumnezeului meu aurul pentru lucrurile de aur, argintul pentru lucrurile de argint, bronzul pentru lucrurile de aramă, fierul pentru lucrurile de fier și lemnul pentru lucrurile lemnoase, de asemenea, pietre de onix, pietre de întărit, pietre de încrustare de diferite culori, tot felul de pietre scumpe și pietre scumpe din belșug."],[3,"În plus, pentru că mi-am pus afecțiunea asupra casei Dumnezeului meu, de vreme ce am o comoară a mea de aur și argint, o dau casei Dumnezeului meu, peste tot ce am pregătit pentru casa sfântă:"],[4,"chiar trei mii de talanți de aur, din aurul Ofirului și șapte mii de talanți de argint curat, cu care să acoperiți zidurile caselor;"],[5,"de aur pentru lucrurile de aur și de argint pentru lucrurile de argint și pentru tot felul de lucrări care trebuie făcute de mâinile meșterilor. Cine se oferă atunci de bunăvoie să se consacre astăzi Domnului?”"],[6,"Atunci căpeteniile caselor părinților și căpeteniile triburilor lui Israel și căpeteniile de mii și de sute, împreună cu conducătorii lucrării împăratului, au oferit de bunăvoie;"],[7,"și au dat pentru slujba Casei lui Dumnezeu cinci mii de talanți de aur și zece mii de dari, zece mii de talanți de argint, optsprezece mii de talanți de aramă și o sută de mii de talanți de fier."],[8,"Oamenii la care s-au găsit pietre prețioase le-au dat în comoara Casei Domnului, sub mâna lui Iehiel Gherșonitul."],[9,"Atunci poporul s-a bucurat, pentru că au oferit de bunăvoie, pentru că cu o inimă desăvârșită au oferit de bunăvoie Domnului; și regele David s-a bucurat și el cu mare bucurie."],[10,"De aceea David a binecuvântat pe Domnul înaintea întregii adunări; și David a zis: „Binecuvântat ești, Doamne, Dumnezeul lui Israel, tatăl nostru, în vecii vecilor."],[11,"A Ta, Doamne, este măreția, puterea, slava, biruința și măreția! Căci tot ce este în ceruri și pe pământ este al tău. A Ta este Împărăția, Doamne, și Tu ești înălțat ca cap mai presus de toți."],[12,"Și bogăția și cinstea vin de la tine și tu stăpânești peste toate! În mâna ta este puterea și puterea! Este în mâna ta să faci mare și să dai putere tuturor!"],[13,"Acum, deci, Dumnezeul nostru, îți mulțumim și lăudăm numele tău slăvit."],[14,"Dar cine sunt eu și care este poporul meu, pe care să-l putem oferi de bunăvoie ca aceasta? Căci toate lucrurile vin de la tine și noi ți-am dat de la tine."],[15,"Căci noi suntem străini înaintea ta și străini, așa cum au fost toți părinții noștri. Zilele noastre pe pământ sunt ca o umbră și nu mai rămâne nimic."],[16,"Doamne, Dumnezeul nostru, tot acest depozit pe care l-am pregătit pentru a-ți zidi o casă pentru Numele Tău sfânt, vine din mâna Ta și este totul al tău."],[17,"De asemenea, știu, Dumnezeule, că încerci inima și îți place în dreptate. În ceea ce mă privește, în dreptatea inimii mele am oferit de bunăvoie toate aceste lucruri. Acum am văzut cu bucurie oamenii tăi, care sunt prezenți aici, oferindu-ți de bunăvoie."],[18,"Domnul, Dumnezeul lui Avraam, al lui Isaac și al lui Israel, părinții noștri, păstrează pentru totdeauna această dorință în gândurile inimii poporului tău și pregătește-le inima pentru tine;"],[19,"și dă-i lui Solomon fiului meu o inimă desăvârșită, ca să păzească poruncile tale, mărturiile tale și poruncile tale, să facă toate aceste lucruri și să zidească palatul pentru care am pregătit.”"],[20,"Atunci David a zis întregii adunări: „Acum binecuvântați pe Domnul, Dumnezeul vostru!”"],[21,"Au adus jertfe Domnului și au adus Domnului arderi de tot în ziua următoare după acea zi, o mie de tauri, o mie de berbeci și o mie de miei, cu jertfele lor de băutură și jertfe din belșug pentru tot Israelul,"],[22,"și a mâncat și a băut înaintea Domnului în ziua aceea cu mare bucurie. L-au făcut împărat a doua oară pe Solomon, fiul lui David, și l-au uns înaintea Domnului ca domn, iar Țadoc ca preot."],[23,"Atunci Solomon s-a așezat pe tronul Domnului ca rege în locul tatălui său David și a prosperat; şi tot Israelul l-a ascultat."],[24,"Toți prinții, oamenii puternici și, de asemenea, toți fiii regelui David s-au supus împăratului Solomon."],[25,"Domnul l-a mărit nespus de mult pe Solomon în ochii întregului Israel și i-a dat o asemenea măreție împărătească, care nu fusese asupra niciunui rege înaintea lui în Israel."],[26,"David, fiul lui Isai, a domnit peste tot Israelul."],[27,"Timpul în care a domnit peste Israel a fost de patruzeci de ani; a domnit șapte ani la Hebron și a domnit treizeci și trei de ani la Ierusalim."],[28,"A murit la o bătrânețe bună, plin de zile, bogății și cinste; și fiul său Solomon a domnit în locul lui."],[29,"Acum, faptele împăratului David, cele dintâi și cele de pe urmă, iată, ele sunt scrise în istoria văzului Samuel și în istoria profetului Natan și în istoria văzului Gad,"],[30,"cu toată domnia și puterea lui și cu evenimentele care l-au implicat pe el, pe Israel și cu toate împărățiile țărilor."]]]];